MultiLanguageItemData['mx'][71972] = {name = "Tinta profética", additional_info = "Objeto de misión\n[q2]Uso: Inscribe una hoja de papiro ligero para hacer una de las fortunas de Sayge.\n[q]\"Se rumorea que esta tinta mágica revela pistas sobre el futuro.\""}
