MultiLanguageItemData['mx'][78917] = {name = "Órdenes Dojani", additional_info = "Objeto de misión\n[q]\"Una serie de dibujos rudimentarios describen unos artefactos mogu específicos que se pueden encontrar en las Ruinas de Dojan.\"\n[q2]<Click derecho para leer>"}
