MultiLanguageItemData['mx'][86525] = {name = "[q3]Fragmento de quitina empapado de sangre", additional_info = "Se liga al recogerlo\nAbalorio\n[q2]Aumenta tu índice de maestría + 6 p.\n[q2]Equipar: Cuando mates a un enemigo que otorgue experiencia u honor, ganarás Furia del Cruento, que te da 0 p. de agilidad durante 2 min. Se acumula hasta 10 veces.\n[q]\"Un fragmento de quitina de Skeer el Cruento bañada en la sangre de sus enemigos.\"\nPrecio de venta:"}
