MultiLanguageItemData['mx'][86529] = {name = "[q3]Dije de manipulador", additional_info = "[q7]Se liga a la tropa\nÚnico-Equipado\nAbalorio\n[q2]Equipar: Los ataques de tu mascota tienen una probabilidad de infligir un 50% de daño de Naturaleza extra pero no más de 26 p. (Probabilidad de que accione: 10%)\nPrecio de venta:"}
MultiLanguageItemData['mx'][86532] = {name = "Bolsa de bombas de gas del Shadopan", additional_info = "Objeto de misión\n[q2]Uso: Coloca una bomba de gas del Shadopan. Es inofensiva para los humanoides que no sean mántides. (20 Seg Reutilización)\n[q]\"Extermina a los mántides.\""}
MultiLanguageItemData['mx'][86533] = {name = "Ámbar resplandeciente", additional_info = "Objeto de misión\nÚnico\n[q]\"El débil brillo sugiere que no se trata de un trozo de ámbar ordinario.\""}
MultiLanguageItemData['mx'][86534] = {name = "Moneda del Shadopan lustrosa", additional_info = "Se liga al recogerlo\nÚnico (10)\nDuración: 18 h (tiempo real)\n[q2]Uso: Lanza una moneda del Shadopan que llama la atención de todos los monstruos cercanos durante 10 s. No rompe el sigilo. Solo se puede utilizar en Sra'vess. (3 Seg Reutilización)\n[q]\"El ruido, y no su valor, distrae a los mántides.\""}
MultiLanguageItemData['mx'][86536] = {name = "Dardo de letargo Wu Kao", additional_info = "Se liga al recogerlo\nÚnico (6)\nDuración: 18 h (tiempo real)\n[q2]Uso: Incapacita al objetivo durante un máximo de 1 min. Se debe estar en modo sigilo. Solo funciona con criaturas que no estén en combate y solo se puede usar en Sra'vess. Cualquier daño infligido reanimará al objetivo. (3 Seg Reutilización)\n[q]\"Un dardo finamente creado que utilizan los Wu Kao.\""}
MultiLanguageItemData['mx'][86541] = {name = "[q0]Glifo carbonizado", additional_info = "Clases: Sacerdote\n[q]\"Aunque parezca que este glifo está quemado por completo y ya no contiene magia, puede que un vendedor no note la diferencia...\"\nPrecio de venta:"}
