MultiLanguageItemData['mx'][86571] = {name = "[q3]Piedra de ligación de Kang", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Le infunde el poder de la piedra, lo que otorga una probabilidad al matar a un oponente de encerrarlo en piedra. (Probabilidad de que accione: 33%, 1m de reutilización) (1 Hora Reutilización)\n[q]\"Los ligadores de piedras mogu utilizan estos catalizadores grabados con runas para transformar la carne en piedra.\""}
MultiLanguageItemData['mx'][86572] = {name = "[q3]Fragmento de terracota", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n[q2]Uso: Invoca un guerrero de terracota para que luche a tu lado durante 10 min. (1 Hora Reutilización)\n[q]\"Imbuido de poderosa magia mogu.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86573] = {name = "[q3]Fragmento de piedra de arco", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Te transformas en una estatua mogu, lo que impide seleccionarte como objetivo durante 5 min. (30 Min Reutilización)\n[q]\"Un fragmento de origen desconocido que rebosa de un poder ancestral.\""}
MultiLanguageItemData['mx'][86574] = {name = "[q0]Elixir de conocimiento antiguo", additional_info = "[q]\"Un ligero susurro sale de la botella.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86575] = {name = "[q3]Cáliz de secretos", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Cedes a tu ira durante 10 s. Mientras está activo, el siguiente golpe de gracia que se realice contra un jugador te transformará en un mogu durante 6.3 s, lo que evitará que realices cualquier acción mientras te recreas. (10 Min Reutilización)\n[q]\"Los rituales para profanar la muerte de un oponente caído son inherentes a la cultura mogu.\""}
MultiLanguageItemData['mx'][86576] = {name = "[q3]Dinastía del acero", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n[q2]Uso: Invoca un torbellino de espadas que lucha por ti durante 10 min. (1 Hora Reutilización)\n[q]\"Las técnicas de esgrima de los mántides son un secreto muy bien guardado.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86577] = {name = "[q3]Vara de formas de ámbar", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Encierra al objetivo en ámbar, lo que impide toda acción durante un máximo de 1 min. Cualquier daño infligido romperá el ámbar. No funciona con jugadores u objetivos de nivel superior a 49. (5 Min Reutilización)\n[q]\"Utilizada por los mántides tejedores de ámbar para hilar estructuras de ámbar endurecido.\""}
MultiLanguageItemData['mx'][86578] = {name = "[q3]Sigilo de guerrero eterno", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Restaura un 15% de salud y maná cada 1 s durante 6 s. Cualquier daño recibido eliminará el frenesí. Solo puede usarse en Pandaria. (5 Min Reutilización)\n[q]\"Concedido al guardia de élite de Shek'zeer por sus servicios a la Emperatriz.\""}
MultiLanguageItemData['mx'][86580] = {name = "[q0]Nenúfar marchito", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Paladín , Cazador , Pícaro , Sacerdote , Caballero de la muerte , Chamán , Mago , Brujo , Monje\n[q]\"El cambio de clima ha secado a este espécimen.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86581] = {name = "[q3]Caracola Agualejana", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Te permite ver a lo lejos y te otorga la facultad de crear gotas de agua. (10 Min Reutilización)\n[q]\"Inscrita con runas jinyu que permiten al usuario comprender la lengua de las olas.\""}
MultiLanguageItemData['mx'][86582] = {name = "[q3]Joya acuática", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Aumenta la velocidad de nado un 50% y permite respiración bajo el agua durante 10 min. Solo puedes usarlo en Pandaria. (1 Hora Reutilización)\n[q]\"Recogida de las fauces de Gokk'lok.\""}
MultiLanguageItemData['mx'][86583] = {name = "[q3]Estandarte de batalla Salyin", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Te fundes con las sombras durante 1 s e invocas a un explorador de guerra Salyin. El explorador de guerra atraerá la atención de los monstruos cercanos y se irá corriendo. Solo eficaz en Pandaria. (10 Min Reutilización)\n[q]\"Manchado con la sangre de muchos aventureros desafortunados.\""}
MultiLanguageItemData['mx'][86584] = {name = "[q3]Caparazón endurecido", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Lanza un caparazón endurecido que desmonta al objetivo. No se puede usar contra objetivos de nivel superior a 49. (15 Min Reutilización)\n[q]\"Parece injusto.\""}
MultiLanguageItemData['mx'][86585] = {name = "[q3]Vellocino de oro", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n[q2]Equipar: Puede provocar que caiga oro extra al matar a un objetivo que otorga experiencia u honor. (Probabilidad de que accione: 10%, 10m de reutilización)\n[q]\"Considerado un símbolo de riqueza y estatus entre los saurok.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86586] = {name = "[q3]Zampoña de Pandaria", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Toca la zampoña, lo que provoca que las alimañas cercanas te sigan durante 15 min. (1 Min Reutilización)"}
MultiLanguageItemData['mx'][86587] = {name = "[q3]Semilla de crecimiento tranquilo", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n[q2]Uso: Invoca un brote tranquilo para que te sane durante 10 min. (1 Hora Reutilización)\n[q]\"Una energía vital vibrante emana de esta semilla.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][86588] = {name = "[q3]Lanzador de fuegos artificiales pandaren", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Prepara un espectáculo pirotécnico deslumbrante. (30 Min Reutilización)\n[q]\"¡Esto es una fiesta!\""}
MultiLanguageItemData['mx'][86589] = {name = "[q3]Reflejo celeste de Ai-Li", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Adopta la ligeramente brillante apariencia del objetivo durante 10 min. (1 Hora Reutilización)\n[q]\"Rodeado por un anillo de nubes en constante cambio.\""}
MultiLanguageItemData['mx'][86590] = {name = "[q3]Esencia de la brisa", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: Crea una brisa suave que aligera tus pasos. Este efecto solo funciona en Pandaria. (1 Hora Reutilización)"}
MultiLanguageItemData['mx'][86591] = {name = "[q3]Plátano mágico", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Lanza un plátano mágico al suelo, lo que hará que la primera persona que lo pise se resbale. (2 H Reutilización)"}
