MultiLanguageItemData['mx'][86593] = {name = "[q3]Pelota de playa hozen", additional_info = "Se liga al recogerlo\nÚnico\nJuguete\n[q2]Uso: ¡Prepárate para la diversión al sol! (1 Hora Reutilización)"}
