MultiLanguageItemData['mx'][89197] = {name = "Semilla de cactus Cortaviento", additional_info = "Se liga al recogerlo\n[q2]Uso: Planta una semilla de cactus Cortaviento.\nRequiere Los Labradores: Venerado\n[q]\"El cactus Cortaviento está cubierto de millones de finas agujas que depuran el aire que lo atraviesa. Las fibras de lanaviento y los trozos de material que vuelan con la brisa quedan atrapados con frecuencia en el cactus.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][89202] = {name = "Semilla de hojarraptor", additional_info = "Se liga al recogerlo\n[q2]Uso: Planta una semilla de hojaraptor.\nRequiere Los Labradores: Venerado\n[q]\"La hojarraptor es una planta carnívora conocida por devorar mures, halcones y otras criaturas pequeñas. Muere tras una sola ingesta, lanza semillas al aire y, a menudo, deja los restos de su presa.\"\nPrecio de venta:"}
