MultiLanguageItemData['mx'][92019] = {name = "El molotov Pantoque", additional_info = "Objeto de misión\n[q2]Uso: Lanza una botella de bazofia ardiente reconstituida a un girocóptero X2 de El Abrasacielos.\n[q]\"Un potente mejunje de sustancias químicas inestables e inflamables con un pañuelo en llamas que sobresale de la parte superior.\""}
