MultiLanguageItemData['mx'][92049] = {name = "Contrato mercenario: mago", additional_info = "[q2]Uso: Contrata a un mago que lanza Luminosidad Arcana sobre jugadores de la Horda cercanos sin coste alguno.\n\nLuminosidad Arcana\n Alcance de 30 m\n Instantáneo\n Requires Mage Infunde luminosidad al objetivo, lo que aumenta su poder con hechizos un 10% y su probabilidad de golpe crítico un 5% durante 1 h. Solo funciona en la Espesura Krasarang."}
MultiLanguageItemData['mx'][92050] = {name = "Contrato mercenario: paladín", additional_info = "[q2]Uso: Contrata a un paladín que lanza Bendición de poderío sobre jugadores de la Horda cercanos sin coste alguno.\n\nBendición de poderío Nivel 35 Alcance de 30 m\n Instantáneo\n Requires Paladin Da a un objetivo amistoso una Bendición que aumenta 59 p. su maestría. Solo funciona en la Espesura Krasarang."}
MultiLanguageItemData['mx'][92051] = {name = "Contrato mercenario: sacerdote", additional_info = "[q2]Uso: Contrata a un sacerdote que lanza Palabra de poder: entereza sobre jugadores de la Horda cercanos sin coste alguno.\n\nPalabra de poder: entereza 4.4% of base mana Alcance de 40 m Instantáneo\n Requires Priest Imbuye de vitalidad al objetivo, lo que aumenta un 10% su aguante durante 1 h. Solo funciona en la Espesura Krasarang."}
MultiLanguageItemData['mx'][92052] = {name = "Contrato mercenario: druida", additional_info = "[q2]Uso: Contrata a un druida que lanza Marca de lo Salvaje sobre jugadores de la Horda cercanos sin coste alguno.\n\nMarca de lo Salvaje\n Alcance de 30 m\n Instantáneo\n Requires Druid Aumenta la fuerza, la agilidad y el intelecto del objetivo amistoso un 5% durante 1 h. Solo funciona en la Espesura Krasarang."}
