MultiLanguageItemData['mx'][93662] = {name = "[q4]Riendas del vociferador de cielos acorazado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura. Las capacidades de esta montura dependen de tu habilidad de equitación y de la ubicación.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Solo aquellas almas heroicas que superan cada desafío que los tiranos mogu ponen a su paso pueden volar sobre un vociferador de los cielos guerrero.\"\nLogro:\nGloria del asaltante atronador\nCategoría:\nCalabozos y bandas"}
MultiLanguageItemData['mx'][93666] = {name = "[q4]Engendro de Horridonte", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Cuando vez que se aproxima un huracán, huyes. Un horridonte pelearía contra él y ganaría.\"\nBotín:\nHorridonte\nZona:\nSolio del Trueno"}
MultiLanguageItemData['mx'][93668] = {name = "Fetiche saurio", additional_info = "Objeto de misión\n[q2]Uso: Usa este fetiche sobre un raptor, un sáurido, un vociferador de cielos o un cuernoatroz en la Jaula de las bestias para tener la posibilidad de controlarlo. Los resultados son impredecibles. (10 Seg Reutilización)"}
