MultiLanguageItemData['mx'][95457] = {name = "Bolsa de semillas de hojarraptor", additional_info = "Se liga al recogerlo\n[q2]Uso: Lanza un puñado de semillas de hojarraptor en un área, lo que las planta en un máximo de 4 parcelas de tierra labrada.\n10 cargas\nRequiere Los Labradores: Exaltado\n[q]\"La hojarraptor es una planta carnívora conocida por devorar mures, halcones y otras criaturas pequeñas. Muere tras una sola ingesta, lanza semillas al aire y, a menudo, deja los restos de su presa.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][95458] = {name = "Bolsa de semillas de hojarraptor", additional_info = "Se liga al recogerlo\n[q2]Uso: Lanza un puñado de semillas de hojarraptor en un área, lo que las planta en un máximo de 4 parcelas de tierra labrada.\n10 cargas\nRequiere Los Labradores: Exaltado\n[q]\"La hojarraptor es una planta carnívora conocida por devorar mures, halcones y otras criaturas pequeñas. Muere tras una sola ingesta, lanza semillas al aire y, a menudo, deja los restos de su presa.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][95467] = {name = "[q2]Patrón: Magnificencia de cuero", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña Magnificencia de cuero.\n[q2]Crea un pellejo magnífico a partir de cuero de neblina una vez al día. En el proceso, puede que adquieras conocimiento extra sobre peletería pandaren y descubras un patrón. Comparte tiempo de reutilización con Magnificencia de escamas.\nRequiere Peletería de Pandaria (1)\n\n\n[q3]Pellejo magnífico\nMaterial de profesión\nPrecio de venta: \nRequiere Cuero de neblina (20)"}
MultiLanguageItemData['mx'][95468] = {name = "[q2]Patrón: Magnificencia de escamas", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña Magnificencia de escamas.\n[q2]Crea un pellejo magnífico a partir de escamas prismáticas una vez al día. En el proceso puede que adquieras conocimiento extra sobre peletería pandaren y descubras un patrón. Comparte tiempo de reutilización con Magnificencia de cuero.\nRequiere Peletería de Pandaria (1)\n\n\n[q3]Pellejo magnífico\nMaterial de profesión\nPrecio de venta: \nRequiere Escama prismática (20)"}
