MultiLanguageItemData['mx'][104227] = {name = "[q2]Técnica: Glifo de Pilar de luz", additional_info = "[q2]Uso: Te enseña a inscribir un Glifo de Pilar de luz.\nRequiere Inscripción de Pandaria (1)\n\n\nGlifo de Pilar de luz\nClases: Paladín\n[q2]Uso: Te enseña permanentemente este glifo.\n\nLas sanaciones críticas con Choque Sagrado a otros jugadores muestran un pequeño pilar de luz brevemente en su ubicación.\nPrecio de venta:\nRequiere Papiro ligero , Tinta onírica (3)"}
MultiLanguageItemData['mx'][104228] = {name = "[q2]Técnica: Glifo de Ángeles", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a inscribir un Glifo de Ángeles.\nRequiere Inscripción de Pandaria (1)\n\n\nGlifo de ángeles\nClases: Sacerdote\n[q2]Uso: Te enseña permanentemente este glifo.\n\nSi lanzas hechizos de sanación, tienes una probabilidad de conseguir alas angelicales. (Probabilidad de que accione: 15%)\nPrecio de venta:\nRequiere Papiro ligero , Tinta del mar (3)"}
MultiLanguageItemData['mx'][104229] = {name = "[q2]Técnica: Glifo del Sha", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a inscribir un Glifo del Sha.\nRequiere Inscripción de Pandaria (1)\n\n\nGlifo del Sha\nClases: Sacerdote\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTransforma a tu maligno de las Sombras en una bestia sha. Exclusivo con: Glifo del engendro de luz Glifo del ser del Vacío\nPrecio de venta:\nRequiere Papiro ligero , Tinta etérea (3)"}
