MultiLanguageItemData['mx'][104287] = {name = "[q2]Péndola de Pluma de Viento", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Aumenta la velocidad sobre una montura terrestre un 30% durante 1 h. Solo se puede usar en Pandaria.\n[q]\"Las plumas de las grullas Pluma de Viento son muy ligeras al tacto y se vuelan a la mínima brisa.\""}
MultiLanguageItemData['mx'][104288] = {name = "[q2]Niebla jade condensada", additional_info = "Se liga al recogerlo\nÚnico (5)\n[q2]Uso: Te rodeas de una niebla densa, lo que permite que te fundas con las sombras durante 10 s. Solo se puede usar en Pandaria. (5 Min Reutilización)\n[q]\"Los bailarines de niebla jade son famosos por mezclarse completamente con la niebla que rodea la isla.\""}
MultiLanguageItemData['mx'][104289] = {name = "[q2]Hierba con resplandor tenue", additional_info = "Se liga al recogerlo\nÚnico (10)\nDuración: 1 día (tiempo real)\n[q2]Uso: Come la hierba, lo que restaura 206 p. de salud cada 1 s durante 10 s.\n[q]\"Parece que esta hierba cuenta con algún tipo de encantamiento natural.\""}
MultiLanguageItemData['mx'][104290] = {name = "[q2]Baba de gusano de seda pegajosa", additional_info = "Se liga al recogerlo\nÚnico (10)\n[q2]Uso: Cubre a un enemigo con seda pegajosa, lo que inmoviliza hasta a las criaturas más fuertes durante 20 s. Solo se puede usar en la Isla Intemporal. (5 Min Reutilización)\n[q]\"Los gusanos de seda de la Isla Intemporal han adaptado una extraña y resistente seda para cazar presas.\""}
