MultiLanguageItemData['mx'][109168] = {name = "[q4]Trituradora de Hierrotriturado", additional_info = "Se liga al equiparlo\nÚnico-Equipado: Fabricado - Warlords (3)\n{A distancia} {Arma de fuego}\n{7 - 13 p. de daño} {Velocidad 3.00}\n(3.3 p. de daño por segundo)\n+5 agilidad\n+7 aguante\nDurabilidad 120 / 120\n[q]\"Para los ingenieros, una obra de arte. Para los cazadores, una herramienta para el arte de matar.\"\nPrecio de venta:"}
