MultiLanguageItemData['mx'][109224] = {name = "Fragmentos de alma Gul'var", additional_info = "Objeto de misión\n[q2]Uso: Combina los fragmentos de almas en la forja en Gul'var para crear la trampa para el alma de Gul'dan."}
