MultiLanguageItemData['mx'][109246] = {name = "Trampa para el alma de Gul'dan", additional_info = "Objeto de misión\n[q2]Uso: Atrapa el alma de Gul'dan, encerrándola para devolverla al Archimago Khadgar en la Avanzada de Lluvia de estrellas. (20 Seg Reutilización)"}
MultiLanguageItemData['mx'][109248] = {name = "Esquemas de arma de asedio", additional_info = "Objeto de misión\nÚnico\n[q]\"El arma detallada en estos planos es brutal y salvaje.\""}
MultiLanguageItemData['mx'][109253] = {name = "[q2]Navaja gnómica suprema", additional_info = "[q2]+10 p. de habilidad en minería de Draenor.\n +10 p. de habilidad en herboristería de Draenor.\n +10 p. de habilidad en desuello de Draenor.\n[q]\"Incluye todas las herramientas de las profesiones.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][109254] = {name = "[q3]Aserradero, nivel 2", additional_info = "Plano de la fortaleza\nSe liga al recogerlo\nÚnico\n[q2]Uso: Proporciona los planos necesarios para mejorar tu Aserradero de la fortaleza al nivel 2.\n\n Level 1\nTe permite marcar árboles pequeños en Draenor para tu recolección. La madera recolectada puede convertirse en pedidos para suministros de la fortaleza.\n\n Level 2\nTe permite marcar árboles intermedios para obtener madera extra.\n\n Level 3\nTe permite marcar árboles grandes para obtener aún más madera.\nRequiere la cadena de misiones del puesto de avanzada de los Pináculos de Arak o nivel 35.\nPrecio de venta:"}
MultiLanguageItemData['mx'][109255] = {name = "[q3]Aserradero, nivel 3", additional_info = "Plano de la fortaleza\nSe liga al recogerlo\nÚnico\n[q2]Uso: Proporciona los planos necesarios para mejorar tu Aserradero de la fortaleza al nivel 3.\n\n Level 1\nTe permite marcar árboles pequeños en Draenor para tu recolección. La madera recolectada puede convertirse en pedidos para suministros de la fortaleza.\n\n Level 2\nTe permite marcar árboles intermedios para obtener madera extra.\n\n Level 3\nTe permite marcar árboles grandes para obtener aún más madera.\nNecesita logro: Mejorando el aserradero\nPrecio de venta:"}
MultiLanguageItemData['mx'][109256] = {name = "[q3]Obras de ingeniería, nivel 2", additional_info = "Plano de la fortaleza\nSe liga al recogerlo\nÚnico\n[q2]Uso: Proporciona los planos necesarios para mejorar tu edificio de Obras de ingeniería al nivel 2.\n\n Level 1\nPermite la producción de objetos y pedidos de ingeniería.\n\n Level 2\nPermite que los seguidores con la característica de ingeniería trabajen aquí, lo que otorga un bonus único. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de ingeniería y permite hasta 21 pedidos a la vez.\nRequiere la cadena de misiones del puesto de avanzada de Talador o nivel 30.\nPrecio de venta:"}
MultiLanguageItemData['mx'][109257] = {name = "[q3]Obras de ingeniería, nivel 3", additional_info = "Plano de la fortaleza\nSe liga al recogerlo\nÚnico\n[q2]Uso: Proporciona los planos necesarios para mejorar tu edificio de Obras de ingeniería al nivel 3.\n\n Level 1\nPermite la producción de objetos y pedidos de ingeniería.\n\n Level 2\nPermite que los seguidores con la característica de ingeniería trabajen aquí, lo que otorga un bonus único. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de ingeniería y permite hasta 21 pedidos a la vez.\nNecesita logro: Realizando más pedidos\nPrecio de venta:"}
MultiLanguageItemData['mx'][109258] = {name = "[q3]Obras de ingeniería, nivel 1", additional_info = "Plano de la fortaleza\nSe liga al recogerlo\nÚnico\n[q2]Uso: Proporciona los planos necesarios para construir un edificio de Obras de ingeniería en tu fortaleza.\n\n Level 1\nPermite la producción de objetos y pedidos de ingeniería.\n\n Level 2\nPermite que los seguidores con la característica de ingeniería trabajen aquí, lo que otorga un bonus único. También permite hasta 14 pedidos por vez.\n\n Level 3\nDesbloquea misiones de ingeniería y permite hasta 21 pedidos a la vez.\nPrecio de venta:"}
MultiLanguageItemData['mx'][109259] = {name = "Libro de hechizos del Consejo de la Sombra", additional_info = "Objeto de misión\n[q]\"Si lo encuentras, lanza el hechizo de la página 42.\""}
MultiLanguageItemData['mx'][109261] = {name = "Caldera del alquimista", additional_info = "Se liga al recogerlo\n[q]\"Brinda cristales metamórficos y catalizadores alquímicos.\"\n[q2]<Click derecho para abrir>"}
MultiLanguageItemData['mx'][109262] = {name = "[q3]Piedra filosofal draénica", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Piedra de alquimista (1)\nAbalorio\n[q2]Aumenta tu índice de maestría + 4 p.\n[q2]Equipar: Cuando sanas o infliges daño tienes la probabilidad de aumentar tu fuerza, agilidad o intelecto 23 p. durante 15 s. Siempre se elige la estadística más elevada. (Probabilidad de que accione: 35%, 55s de reutilización)\n[q2]Equipar: Aumenta el efecto de las pociones de sanación y maná en su portador en un 40%. Este efecto no se acumula.\nRequiere Alquimia de Draenor (1)\n[q]\"Se puede usar para transmutar en vez de una piedra filosofal.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][109557] = {name = "Suero de mutación", additional_info = "Objeto de misión\nÚnico\n[q]\"Úsalo sobre Grulk para restaurar su fuerza mutante.\""}
MultiLanguageItemData['mx'][109558] = {name = "[q3]Un tratado sobre la alquimia de Draenor", additional_info = "Se liga al recogerlo\nÚnico\nUso: Te enseña Alquimia de Draenor y varias recetas.\nRequiere Alquimia (1)\n[q]\"Una introducción a los secretos de la alquimia de Draenor.\""}
MultiLanguageItemData['mx'][109574] = {name = "[q3]Buzón gomoso", additional_info = "Se liga al usarlo\nÚnico: Objeto de Taller de ingeniería (1)\n[q2]Uso: Crea un buzón portátil durante 5 min. (3 H Reutilización)\n3 cargas\n[q]\"Aunque suele ser demasiado complicado para una persona común, este buzón en particular trae botones extra grandes e instrucciones.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][109575] = {name = "Auch'naaru", additional_info = "Objeto de misión\n[q]\"Uno de los tres fragmentos del Corazón de Auchindoun.\""}
MultiLanguageItemData['mx'][109576] = {name = "[q3]Excavación Caída de la luna, nivel 2", additional_info = "Plano de la fortaleza\nSe liga al recogerlo\nÚnico\nRequiere cualquier raza de la Alianza\n[q2]Uso: Proporciona los planos necesarios para mejorar tu Excavación Caída de la Luna al nivel 2.\n\n Level 1\nPermite a los jugadores extraer piedra draénica de nodos minerales en Draenor. La piedra draénica puede convertirse en pedidos para minerales de Draenor.\n\n Level 2\nPermite que los seguidores con la característica de minería trabajen aquí, lo que otorga una bonificación única. Además, abre un pozo de mina nuevo que permite el acceso a nodos minerales extra y hasta 14 pedidos de una vez.\n\n Level 3\nUn último pozo de mina permite el acceso a nodos minerales ricos. También, los guardias de la fortaleza patrullarán tu mina, manteniendo alejados a los goren hostiles. Además, permite hasta 21 pedidos a la vez.\nRequiere Mina\nPrecio de venta:"}
MultiLanguageItemData['mx'][109577] = {name = "[q3]Herbario, nivel 2", additional_info = "Plano de la fortaleza\nSe liga al recogerlo\nÚnico\n[q2]Uso: Proporciona los planos necesarios para mejorar tu Herbario al nivel 2.\n\n Level 1\nHace que las semillas draénicas se transformen en hierbas cada día y haya nodos de herboristería disponibles en el jardín.\n\n Level 2\nPermite que los seguidores con la característica de herboristería trabajen aquí, lo que les otorga una bonificación única. Además, aumenta la cantidad de hierbas que pueden recolectarse en el jardín y permite hasta 14 pedidos a la vez.\n\n Level 3\nHace crecer un árbol de frutos de Draenor único en tu jardín que da beneficios de comida. Además, permite hasta 21 pedidos a la vez.\nRequiere Herbario\nPrecio de venta:"}
MultiLanguageItemData['mx'][109578] = {name = "[q3]Choza de pesca", additional_info = "Plano de la fortaleza\nSe liga al recogerlo\nÚnico\n[q2]Uso: Proporciona los planos necesarios para construir la Choza de pesca de la fortaleza.\n\n Level 1\nPermite que un pez pequeño de Draenor sea atrapado en aguas de la fortaleza y otorga acceso a misiones de pesca diarias.\n\n Level 2\nPermite que un pez mediano de Draenor sea atrapado en aguas de la fortaleza.\n\n Level 3\nPermite atrapar enormes peces de Draenor en las aguas de la fortaleza. Además, te otorga la probabilidad de atrapar a un pez único que puede usarse para atraer a misteriosas criaturas a la orilla.\nPrecio de venta:"}
MultiLanguageItemData['mx'][109584] = {name = "[q2]Misiva ogra", additional_info = "[q]\"Piedra angular que puede completar artefactos de arqueología ogra a los que les faltan piezas.\"\nPrecio de venta:"}
