MultiLanguageItemData['mx'][112047] = {name = "Receta: tintura transmórfica", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer una tintura transmórfica.\nRequiere Alquimia de Draenor (1)\nPrecio de venta:\nTintura transmórfica\n[q2]Uso: Invierte por un rato el género de quien lo bebe.\nPrecio de venta:\nRequiere Aceite creciente , Hierbaescarcha (5)"}
MultiLanguageItemData['mx'][112049] = {name = "Receta: catalizador alquímico - Epilobio", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer una caldera de alquimista de epilobio.\n[q2]Genera los componentes necesarios para crear los objetos de alquimia más poderosos de Draenor. Solo se puede hacer una vez al día. Comparte el tiempo de reutilización con otras calderas del alquimista.\nRequiere Alquimia de Draenor (1)\nPrecio de venta:"}
MultiLanguageItemData['mx'][112050] = {name = "Receta: catalizador alquímico - Atrapamoscas", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer una caldera de alquimista de atrapamoscas de Gorgrond.\n[q2]Genera los componentes necesarios para crear los objetos de alquimia más poderosos de Draenor. Solo se puede hacer una vez al día. Comparte el tiempo de reutilización con otras calderas del alquimista.\nRequiere Alquimia de Draenor (1)\nPrecio de venta:"}
MultiLanguageItemData['mx'][112051] = {name = "Receta: catalizador alquímico - Florestrella", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer una caldera de alquimista de Florestrella.\n[q2]Genera los componentes necesarios para crear los objetos de alquimia más poderosos de Draenor. Solo se puede hacer una vez al día. Comparte el tiempo de reutilización con otras calderas del alquimista.\nRequiere Alquimia de Draenor (1)\nPrecio de venta:"}
MultiLanguageItemData['mx'][112052] = {name = "Receta: catalizador alquímico - Florflechada", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer una caldera de alquimista de florflechada.\nRequiere Alquimia de Draenor (1)\nPrecio de venta:\n[q2]Catalizador alquímico\nMaterial de profesión\n[q]\"Cataliza reacciones que, de otro modo, llevarían miles de años, y por eso es esencial para la alquimia de Draenor.\"\nRequiere Espíritu primigenio , Epilobio (2), Atrapamoscas de Gorgrond (2), Florflechada de Nagrand (2), Borraja (2), Orquídea de Talador (2)"}
