MultiLanguageItemData['mx'][115519] = {name = "[q3]Frasco del moralmente obligado", additional_info = "[q7]Se liga a la tropa\n[q2]Uso: Aumenta un 20% durante 1 h el honor obtenido de los objetivos y triunfos en el campo de batalla. Este efecto perdura más allá de la muerte. (5 Seg Reutilización)"}
MultiLanguageItemData['mx'][115520] = {name = "[q0]Frasco de conquista estropeado", additional_info = "[q7]Se liga a la tropa\nÚnico (5)\nPrecio de venta:"}
MultiLanguageItemData['mx'][115521] = {name = "[q3]Distintivo de adaptación de combatiente primigenio", additional_info = "Warlords Temporada 1\nSe liga al recogerlo\nAbalorio\n[q2]Aumenta tu índice de maestría + 7 p.\nRequiere cualquier raza de la Alianza\n[q2]Uso: Aumenta versatilidad 20 p. durante 20 s. (1 Min Reutilización)\nRequiereVanguardia de Wrynn\n: Amistoso\nPrecio de venta:"}
MultiLanguageItemData['mx'][115522] = {name = "Fusta veloz", additional_info = "Ashran\nSe liga al recogerlo\nÚnico (10)\n[q2]Uso: Te permite montar instantáneamente durante 1 h mientras estás en Ashran.\nRequiereVanguardia de Wrynn\n: Honorable\nPrecio de venta:"}
MultiLanguageItemData['mx'][115523] = {name = "[q5]Brazo arrancado de Puño Negro", additional_info = "Objeto de misión\nÚnico\n[q]\"¿Es carne... o piedra?\""}
MultiLanguageItemData['mx'][115524] = {name = "[q2]Cristal de taladita", additional_info = "Se liga al recogerlo\nMaterial de profesión\n[q]\"Una gema sintética versátil que se usa en muchas recetas de joyería de Draenor.\""}
MultiLanguageItemData['mx'][115525] = {name = "[q3]Cara de ogro aterradora", additional_info = "Único\n[q2]Uso: Adoptas la forma de un orco aterrador durante 10 min. (Probabilidad de que accione: 10%, 30s de reutilización) (50 Min Reutilización)\n5 cargas"}
MultiLanguageItemData['mx'][115526] = {name = "[q3]Recristalizador de taladita", additional_info = "[q2]Uso: Crea nuevamente las propiedades secundarias de objetos de joyería de Warlords con nivel de objeto 45 o inferior."}
