MultiLanguageItemData['mx'][115530] = {name = "Marcador de objetivos N.U.K.U.L.A.R.", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 1 día (tiempo real)\n[q2]Uso: Marca una ubicación objetivo, lo que provoca que una poderosa ojiva explote ahí luego de 10 s, la explosión inflige 76892 p. de daño de Fuego a todos los enemigos en un radio de 20 m. (1 Hora Reutilización)\n2 cargas\n[q]\"Obviamente significa algo muy técnico.\""}
MultiLanguageItemData['mx'][115531] = {name = "Poción arremolinada de Ashran", additional_info = "Ashran\n[q2]Uso: Sin dudas, el efecto de esta poción es tan potente como su olor. (2 Min Reutilización)"}
MultiLanguageItemData['mx'][115532] = {name = "Gafas de rayos X endebles", additional_info = "Ashran\nSe liga al recogerlo\n[q2]Uso: Otorga visión para ver dentro de las bolsas de botín de los jugadores enemigos, lo que indica quién lleva fragmentos del artefacto. Dura 1 h.\nRequiereVanguardia de Wrynn\n: Honorable"}
MultiLanguageItemData['mx'][115533] = {name = "Vial de suero refinado", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Aplica el suero al goblin infectado y débil en Punta Silbapellizco. (5 Seg Reutilización)"}
MultiLanguageItemData['mx'][115534] = {name = "Pistola de bengalas de Penny", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Dispara una bengala. (2 Min Reutilización)\n[q]\"Gatillo modificado para disparar fácilmente.\""}
MultiLanguageItemData['mx'][115535] = {name = "[q4]Grebas de placas óseas cráneogro", additional_info = "Se liga al recogerlo\n{Piernas} {Placas}\n15 armadura\n+5 [Fuerza o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 120 / 120\nClases: Caballero de la muerte\n[q]Armadura de batalla de placas óseas cráneogro (0/5)\n[q0]Grebas de placas óseas cráneogro\nEspaldares de placas óseas cráneogro\nCoraza de placas óseas cráneogro\nGuanteletes de placas óseas cráneogro\nGran yelmo de placas óseas cráneogro\n[q8]Conjunto antiguo: la bonificación no está activa\n[q0](2) Conjunto Sangre: Golpe letal reduce el tiempo de reutilización de Sangre vampírica 1 s.\n(2) Conjunto Escarcha: Activar Pilar de Escarcha genera 30 p. de poder rúnico.\n(2) Conjunto Profano: Tu mascota inflige un 120% de daño adicional mientras Transformación oscura está activa.\n(4) Conjunto Sangre: Mientras Sangre vampírica está activo, tu Escudo de sangre no puede ser reducido por debajo del 3% de tu salud máxima.\n(4) Conjunto Escarcha: Mientras Pilar de Escarcha está activo, tus ataques especiales atrapan un alma en tu arma de runas. Cuando Pilar de Escarcha se desvanece, tu arma de runas descarga las almas en tu objetivo actual, lo que inflige ([3.51% of Attack Power])% p. de daño por alma.\n(4) Conjunto Profano: Cuando activas Transformación oscura, 1 de tus runas se reinician automáticamente.\nPrecio de venta:"}
