MultiLanguageItemData['mx'][116655] = {name = "[q3]Trotacantilados pelajemarchito", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Trotacantilados pelajemarchito.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Muescas diminutas cubren las pezuñas de esta variación de uñagrieta, lo que le permite escalar con firmeza regiones montañosas en busca de comida.\"\nVendedor:\nComerciante Araanda\nZona:\nCaída de la Luna\nCosto:\n\nVendedor:\nComerciante Darakk\nZona:\nMuro de Escarcha\nCosto:"}
MultiLanguageItemData['mx'][116656] = {name = "[q3]Cascohielo entrenado", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Cascohielo entrenado.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"No fue hasta que conseguiste esta montura que entendiste la magnitud de las pruebas a las que te pondría Draenor. ¡El pelo de uñagrieta se pega a todo!\"\nFuente:\nEstablos de la fortaleza"}
MultiLanguageItemData['mx'][116657] = {name = "[q3]Piel de cuero anciano", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Piel de cuero anciano.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete"}
MultiLanguageItemData['mx'][116658] = {name = "[q3]Cascohielo de la tundra", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Cascohielo de la tundra.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Una capa traslúcida de cabello cubre el pellejo curtido de esta raza, lo que actúa como un aislamiento perfecto para ambientes fríos.\"\nBotín:\nVenganza, Garramuerte, Puño de terror, Rodador maldito\nZona:\nJungla Tanaan"}
MultiLanguageItemData['mx'][116659] = {name = "[q4]Toro Pezuña de Sangre", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Toro Pezuña de Sangre.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Desde hace tiempo los miembros del clan Grito de Guerra cazan a estas uñagrietas para usar su piel de tonos carmesí en los estandartes de batalla.\"\nBotín:\nNakk el Tronador\nUbicación:\nNagrand"}
MultiLanguageItemData['mx'][116660] = {name = "[q4]Destructor patahierro", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Destructor patahierro.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Se dice que Puño Negro diseñó personalmente los armamentos ígneos usados en las monturas de batalla de uñagrieta de la Horda de Hierro.\"\nBotín:\nPuño Negro\nUbicación:\nFundición de Roca Negra (Mítico)"}
MultiLanguageItemData['mx'][116661] = {name = "[q4]Trotacampos moteado", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Trotacampos moteado.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"La trompa larga del elekk le permite olfatear fuentes de comida, evadir el peligro y robar bocadillos de tu bolsa cuando no estás mirando.\"\nBotín:\nLuk'hok\nZona:\nNagrand"}
MultiLanguageItemData['mx'][116662] = {name = "[q3]Trotacampos entrenado", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Trotacampos entrenado.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Los draenei perfeccionaron la cría de elekk hace años; adornaban a las criaturas con cristales imbuidos de luz para hacerlos más dóciles.\"\nMisión:\nEstablos de la fortaleza"}
MultiLanguageItemData['mx'][116663] = {name = "[q3]Dentoperla Pielsombra", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Dentoperla Pielsombra.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Algunas leyendas dicen que los draenei se hicieron amigos de los elekk por primera vez cuando una de las bestias salvó a un explorador herido de una jauría de vainitas despiadadas.\"\nBotín:\ntesoro olvidado del invasor"}
MultiLanguageItemData['mx'][116664] = {name = "[q3]Rocapiel polvoriento", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Rocapiel polvoriento.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereConsejo de Exarcas\n: Exaltado\nYa conocido\nPrecio de venta:\n[q]\"Desde que adquiriste esta montura, te persiguen sueños de fiebre extraños de elekk que desfilan con bombos, platillos y toda la fanfarria.\"\nVendedor:\nVindicador Nuurem\nFacción:\nConsejo de Exarcas - Exaltado\nUbicación:\nEscudo de Tormenta\nCosto:\n + 5000"}
MultiLanguageItemData['mx'][116665] = {name = "[q3]Colmihierro acorazado", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Colmihierro acorazado.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereDefensa Sha'tari\n: Exaltado\nPrecio de venta:\n[q]\"Se dice que el elekk no olvida. Con razón detestan a la Horda de Hierro, después de cómo los torturaban los orcos.\"\nVendedor:\n\nFacción:\nDefensa Sha'tari - Exaltado\nUbicación:\nPuesto de venta de la fortaleza\nCosto:\n + 5000"}
MultiLanguageItemData['mx'][116666] = {name = "[q3]Jabaguerrero de acero negro", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Jabaguerrero de acero negro.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Se rehúsa a correr a menos que su cabeza esté cubierta de metal pesado y con pinchos. Puro ego.\"\nLogro:\nhermandad Gloria del asaltante de Draenor"}
MultiLanguageItemData['mx'][116667] = {name = "[q3]Jabaguerrero rocamuela", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Jabaguerrero rocamuela.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"No es el casco de metal lo que atrae a sus parejas; es esa divina cresta mohicana.\"\nVendedor:\nComerciante Araanda\nZona:\nCaída de la Luna\nCosto:\n\nVendedor:\nComerciante Darakk\nZona:\nMuro de Escarcha\nCosto:"}
MultiLanguageItemData['mx'][116668] = {name = "[q3]Jabaescarcha acorazado", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Jabaescarcha acorazado.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Tiene una dieta casi por completo de frutos del bosque. Aunque también le resultan muy apetitosos los seres fuera de este mundo.\"\nLogro:\nCría de animales avanzada"}
MultiLanguageItemData['mx'][116669] = {name = "[q3]Picovaja acorazado", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Picovaja acorazado.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Nunca... jamás... NUNCA... dejes que te sienta olor a panceta.\"\nBotín:\nVenganza, Garramuerte, Puño de terror, Rodador maldito\nZona:\nJungla Tanaan"}
MultiLanguageItemData['mx'][116670] = {name = "[q3]Jabaguerrero de las llanuras congeladas", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Jabaguerrero de las llanuras congeladas.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Si no tuviera ese genial anillo de colmillo, se sentiría tan tonto vestido así...\"\nLogro:\nGloria del héroe de Draenor"}
MultiLanguageItemData['mx'][116671] = {name = "[q3]Dentosangre salvaje", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Dentosangre salvaje.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereLos Acechadores de sable\n: Honorable\n\n\n[q]\"Si quieres un viaje tranquilo, ve a buscar un \"animalito para domesticar\" o algo.\"\nVendedor:\nZ'tenga el Caminante\nZona:\nJungla Tanaan\nFacción:\nLos Acechadores de sable - Honorable\nCosto:\n1000"}
MultiLanguageItemData['mx'][116672] = {name = "[q3]Picovaja domesticado", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Picovaja domesticado.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereSociedad de preservación de Bonvapor\n: Exaltado\nYa conocido\nPrecio de venta:\n[q]\"Domesticado no necesariamente significa \"amigable\". Trae algunos bocadillos.\"\nVendedor:\nGazrix Engranaje Seguro / Mimi Contertulio\nFacción:\nSociedad de \"Preservación\" de Bonvapor - Exaltado\nUbicación:\nEscudo de Tormenta / Lanza de Guerra\nCosto:\n + 5000"}
MultiLanguageItemData['mx'][116673] = {name = "[q3]Morrofrío gigante", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Morrofrío gigante.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"No solo tiene el hocico frío, sino también húmedo. No es la manera más linda de despertar.\"\nBotín:\ntesoro olvidado del invasor"}
MultiLanguageItemData['mx'][116674] = {name = "[q4]Gran colmigris", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Te enseña a invocar esta montura.\n[q2]Invoca y retira a tu Gran colmigris.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Cambia los colmillos una vez al año. Es muy tímido hasta que le vuelven a crecer.\"\nBotín:\nGorok\nZona:\nCresta Pirofrío"}
