MultiLanguageItemData['mx'][118310] = {name = "Idea de receta: suculento filete de elekk", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un suculento filete de elekk.\n[q2]Receta para 4 porciones. El número real de porciones varía según la habilidad para cocinar. Pueden surgir nuevas ideas de recetas mientras se está cocinando.\nRequiere Cocina de Draenor (1)\n\n\nSuculento filete de elekk\n[q2]Uso: Restaura 8173 p. de salud y ( 2125 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 segundos, te alimentarás bien y obtendrás 14 p. de aguante durante 1 h.\n\n Al probar este plato, quizás consigas la receta.\nPrecio de venta: \nRequiere Carne cruda de elekk (5)"}
MultiLanguageItemData['mx'][118311] = {name = "Idea de receta: jamón de Roca Negra", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un jamón de Roca Negra.\n[q2]Receta para 4 porciones. El número real de porciones varía según la habilidad para cocinar. Pueden surgir nuevas ideas de recetas mientras se está cocinando.\nRequiere Cocina de Draenor (1)\n\n\nJamón de Roca Negra\n[q2]Uso: Restaura 8173 p. de salud y ( 2125 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 segundos, te alimentarás bien y obtendrás 6 p. de golpe crítico durante 1 h.\n\n Si pruebas este plato, es posible que consigas la receta.\nPrecio de venta: \nRequiere Carne cruda de jabalí (5)"}
