MultiLanguageItemData['mx'][122555] = {name = "Receta: sushi de durmiente", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a preparar sushi de durmiente.\nRequiere Cocina de Draenor (1)\nPrecio de venta: \nSushi de durmiente\n[q2]Uso: Restaura 8173 p. de salud y ( 2125 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si pasas al menos 10 s comiendo, te alimentarás bien y obtendrás 14 p. de maestría durante 1 h.\nPrecio de venta: \nRequiere Carne de durmiente gordo (12), Carne de pez sable curvado (6)"}
MultiLanguageItemData['mx'][122556] = {name = "Receta: esturión en mantequilla", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a preparar esturión en mantequilla.\nRequiere Cocina de Draenor (1)\nPrecio de venta: \nEsturión en mantequilla\n[q2]Uso: Restaura 8173 p. de salud y ( 2125 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, te alimentarás bien y obtendrás 14 p. de celeridad durante 1 h.\nPrecio de venta: \nRequiere Carne de esturión ciego del lago (12), Carne de pez sable curvado (6)"}
MultiLanguageItemData['mx'][122557] = {name = "Receta: Lobo de mar jumbo", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a preparar lobo de mar jumbo.\nRequiere Cocina de Draenor (1)\nPrecio de venta: \nLobo de mar Jumbo\n[q2]Uso: Restaura 8173 p. de salud y ( 2125 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, te alimentarás bien y obtendrás 14 p. de versatilidad durante 1 h.\nPrecio de venta: \nRequiere Carne de vagador sin quijada (12), Carne de pez sable curvado (6)"}
MultiLanguageItemData['mx'][122558] = {name = "Receta: anguila al escabeche", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a preparar anguila al escabeche.\nRequiere Cocina de Draenor (1)\nPrecio de venta: \nAnguila al escabeche\n[q2]Uso: Restaura 8173 p. de salud y ( 2125 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 segundos, te alimentarás bien y obtendrás 14 p. de golpe crítico durante 1 h.\nPrecio de venta: \nRequiere Carne de anguila tragona abisal (12), Carne de pez sable curvado (6)"}
