MultiLanguageItemData['mx'][122710] = {name = "Receta: alquimia primigenia", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a fabricar un catalizador alquímico sin parar.\nRequiere Alquimia de Draenor (1)\n\n\n[q2]Catalizador alquímico\nMaterial de profesión\n[q]\"Cataliza reacciones que, de otro modo, llevarían miles de años, y por eso es esencial para la alquimia de Draenor.\"\nRequiere Espíritu primigenio , Epilobio (2), Atrapamoscas de Gorgrond (2), Florflechada de Nagrand (2), Borraja (2), Orquídea de Talador (2)"}
MultiLanguageItemData['mx'][122711] = {name = "Fórmula: atadura temporal", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a crear cristales temporales fracturados sin parar.\nRequiere Encantamiento de Draenor (1)\n\n\n[q4]Cristal temporal fisurado\n[q2]Uso: Combina 10 cristales temporales fracturados para formar un cristal temporal.\nMaterial de profesión\nRequiere Espíritu primigenio , Fragmento luminoso"}
MultiLanguageItemData['mx'][122712] = {name = "Esquema: soldadura primigenia", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a crear partes de amortiguador sin parar.\nRequiere Ingeniería de Draenor (1)\n\n\n[q2]Piezas de resorte de engranaje\nSe liga al recogerlo\nMaterial de profesión\n[q]\"Lo último en adaptabilidad, los ingenieros que crean o arreglan aparatos complejos adoran estas piezas.\"\nPrecio de venta:\nRequiere Espíritu primigenio , Mena de Roca Negra (5), Mena de hierro genuino (5)"}
MultiLanguageItemData['mx'][122713] = {name = "Técnica: el espíritu de guerra", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a fabricar pinturas de guerra sin parar.\nRequiere Inscripción de Draenor (1)\nPrecio de venta: \n[q2]Pinturas de guerra\nSe liga al recogerlo\nMaterial de profesión\nRequiere Espíritu primigenio , Pigmento cerúleo (4)"}
MultiLanguageItemData['mx'][122714] = {name = "Boceto: Talla de gemas primigenia", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un cristal de taladita sin parar.\nRequiere Joyería de Draenor (1)\n\n\n[q2]Cristal de taladita\nSe liga al recogerlo\nMaterial de profesión\n[q]\"Una gema sintética versátil que se usa en muchas recetas de joyería de Draenor.\"\nRequiere Espíritu primigenio , Mena de Roca Negra (5), Mena de hierro genuino (5)"}
MultiLanguageItemData['mx'][122715] = {name = "Patrón: Trabajo en cuero espiritual", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer cuero pulido sin parar.\nRequiere Peletería de Draenor (1)\n\n\n[q2]Cuero pulido\nSe liga al recogerlo\nMaterial de profesión\n[q]\"Duros y flexibles, se usan para la peletería en Draenor.\"\nPrecio de venta:\nRequiere Espíritu primigenio , Pellejo de animal crudo (10)"}
MultiLanguageItemData['mx'][122716] = {name = "Patrón: Tejido primigenio", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una tela tejemaleficios sin parar.\nRequiere Sastrería de Draenor (1)\n\n\n[q2]Tela tejemaleficios\nSe liga al recogerlo\nMaterial de profesión\n[q]\"Piel tejida en tela fina. Es la base para gran parte de la sastrería en Draenor.\"\nPrecio de venta: \nRequiere Espíritu primigenio , Piel suntuosa (10)"}
