MultiLanguageItemData['mx'][127871] = {name = "Quemador de llama vil agotado", additional_info = "Objeto de misión\nÚnico\n[q]\"Este quemador era antaño capaz de contener una poderosa llama de energía ley, algo muy útil en la alquimia.\"\nPrecio de venta:"}
