MultiLanguageItemData['mx'][127875] = {name = "Filtro de seda shal'dorei", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Si no estuviera desgarrada, esta tela sería ideal para filtrar fluidos alquímicos.\""}
