MultiLanguageItemData['mx'][127884] = {name = "[q3]Lanzador de humo vil", additional_info = "Equipamiento naval\nSe liga al recogerlo\n[q2]Uso: Equipa una nave con lanzadores de humo vil.\n\nContrarresta:\n Primer golpe\nRequiere un plano, visto por última vez cerca de la Forja Vil.\nPrecio de venta:"}
MultiLanguageItemData['mx'][127885] = {name = "[q3]Tripulación salada", additional_info = "Se liga al recogerlo\n[q2]Uso: Contrata a una tripulación salada para tu buque de guerra.\n[q]\"La tripulación lo ha visto todo y tienen los sombreros para probarlo. Aumenta un 10% la probabilidad de terminar misiones con éxito.\""}
MultiLanguageItemData['mx'][127886] = {name = "[q3]Inhundible", additional_info = "Equipamiento naval\nSe liga al recogerlo\n[q2]Uso: Equipa una nave con Inhundible.\n\nSalva a la nave de un golpe devastador, rodeándola con un escudo impenetrable. Inhundible se destruye cuando se activa.\nRequiere un plano, visto por última vez en manos de un vendedor en la Jungla Tanaan.\nPrecio de venta:"}
MultiLanguageItemData['mx'][127887] = {name = "[q3]Almacén de comida", additional_info = "Se liga al recogerlo\n[q2]Uso: Equipa un buque de guerra con un almacén de comida.\n[q]\"Agrega espacio para llevar más alimentos en la nave, esto mejora la moral y el éxito en misiones largas.\""}
MultiLanguageItemData['mx'][127888] = {name = "[q3]Escáner aéreo automatizado", additional_info = "Equipamiento naval\nSe liga al recogerlo\n[q2]Uso: Equipa una nave con un escáner aéreo automatizado.\n\nAsiste a: portanaves\nPrecio de venta:"}
