MultiLanguageItemData['mx'][127893] = {name = "[q3]Módulo de recuperación de restos", additional_info = "Se liga al recogerlo\n[q2]Uso: Equipa un buque de guerra con un módulo de recuperación de restos.\n[q]\"Cuando se utiliza en una misión exitosa, filtra las aguas circundantes y devuelve una caja llena de chatarra útil.\""}
MultiLanguageItemData['mx'][127894] = {name = "[q3]Red de pesca Tuskarr", additional_info = "Equipamiento naval\nSe liga al recogerlo\n[q2]Uso: Equipa una nave con una red de pesca colmillarr.\n\nUna red de pesca amarrada a la parte trasera del barco, cortesía de los colmillarr. Suministra peces cuando vuelves de una misión exitosa.\nRequiere un plano, visto por última vez en manos de un vendedor en la Jungla Tanaan.\nPrecio de venta:"}
MultiLanguageItemData['mx'][127895] = {name = "[q3]Catalejo fantasmal", additional_info = "Equipamiento naval\nSe liga al recogerlo\n[q2]Uso: Equipa una nave con un catalejo fantasmal.\n\nUn catalejo largo que parece no mostrar nada cuando lo usas. Quizás sea útil.\nRequiere plano de Catalejo fantasmal.\nPrecio de venta:"}
MultiLanguageItemData['mx'][127896] = {name = "[q3]Tanques de combustible nitro", additional_info = "Se liga al recogerlo\n[q2]Uso: Equipa un buque de guerra con tanques de combustible nitro.\n[q]\"Permite que la nave queme combustible nitro, lo que hace que llegue más rápido a su destino.\""}
MultiLanguageItemData['mx'][127897] = {name = "La espada de la verdad", additional_info = "Objeto de misión\n[q2]Uso: Clava la espada Cresta Cuervo en la ubicación deseada. (3 Seg Reutilización)\n[q]\"Debajo de una gruesa capa de mugre, brilla la espada.\""}
MultiLanguageItemData['mx'][127898] = {name = "Receta: poción de sanación ancestral", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de sanación ancestral.\n[q2]Mezcla una poción de sanación ancestral en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nYa conocido\nPrecio de venta: \nPoción de sanación ancestral\n[q2]Uso: Restaura 6000 p. de salud. (5 Min Reutilización)\nPrecio de venta:\nRequiere Semilla de yseralina (4), Vial de cristal"}
MultiLanguageItemData['mx'][127899] = {name = "Receta: poción de maná ancestral", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de maná ancestral.\n[q2]Mezcla una poción de maná ancestral en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nYa conocido\nPrecio de venta: \nPoción de maná ancestral\n[q2]Uso: Restaura 2000 p. de maná. (5 Min Reutilización)\nPrecio de venta:\nRequiere Semilla de yseralina (5), Vial de cristal"}
MultiLanguageItemData['mx'][127900] = {name = "Receta: poción de rejuvenecimiento ancestral", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de rejuvenecimiento ancestral.\n[q2]Mezcla una poción de rejuvenecimiento ancestral en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nYa conocido\nPrecio de venta: \nPoción de rejuvenecimiento ancestral\n[q2]Uso: Restaura 6000 p. de salud y 1500 p. de maná. (5 Min Reutilización)\nPrecio de venta: \nRequiere Poción de sanación ancestral , Poción de maná ancestral"}
MultiLanguageItemData['mx'][127901] = {name = "Receta: jarabe de magia pura", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un jarabe de magia pura.\n[q2]Mezcla una jarabe de magia pura en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere el Quemador de llama vil\nYa conocido\nPrecio de venta: \nJarabe de magia pura\n[q2]Uso: Tómatela toda.\nPrecio de venta:\nRequiere Aethril (20), Poción de sanación ancestral"}
MultiLanguageItemData['mx'][127902] = {name = "Receta: elixir silvano", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un elixir silvano.\n[q2]Mezcla un elíxir Sylvan en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere los Corchos avanzados\nYa conocido\nPrecio de venta: \nElixir Sylvan\n[q2]Uso: Transfórmate en árbol. Tú y los jugadores que reposan bajo tu sombra terminan bien descansados, lo que aumenta todas las estadísticas un 10%.\nPrecio de venta:\nRequiere Frondasueño (5), Poción de sanación ancestral"}
MultiLanguageItemData['mx'][127903] = {name = "Receta: elixir de avalancha", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un elixir de avalancha.\n[q2]Mezcla un elíxir de avalancha en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere el Frasco para mezclas de doble cámara\nYa conocido\nPrecio de venta: \nElixir de avalancha\n[q2]Uso: Al caer una gran distancia, te transformas en una avalancha. Cuando aterrizas, infliges 1500 p. de daño a todos los enemigos en un radio de 5 m. (5 Min Reutilización)\nPrecio de venta:\nRequiere Vulpinia (5), Poción de maná ancestral"}
MultiLanguageItemData['mx'][127904] = {name = "Receta: Brebajeskaggl", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un Brebajeskaggl.\n[q2]Mezcla un brebajeskaggl en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere la Pólvora precipitante\nYa conocido\nPrecio de venta: \nBrebajeskaggl\n[q2]Uso: Entra al reino espiritual, lo cual otorga invisibilidad a quien lo ingiere durante 18 s. No funciona en niveles superiores a 50. (5 Min Reutilización)\nPrecio de venta:\nRequiere Fjarnskaggl (5), Poción de maná ancestral"}
MultiLanguageItemData['mx'][127905] = {name = "Receta: poción de soplo aéreo", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de soplo aéreo.\n[q2]Mezcla una poción de soplo aéreo en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere el Filtro de seda Shaldorei\nYa conocido\nPrecio de venta: \nPoción de soplo aéreo\n[q2]Uso: Aumenta la velocidad de movimiento un 150% y hace flotar a quien bebe la poción. Dura 8 s. No funciona en niveles superiores a 50. (5 Min Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar (4), Poción de rejuvenecimiento ancestral"}
MultiLanguageItemData['mx'][127906] = {name = "Receta: piedra de alquimista infernal", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una piedra de alquimista infernal.\n[q2]Fabrica una piedra de alquimista infernal en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere el Crisol de aliento de demonio\nPrecio de venta: \n[q4]Piedra de alquimista infernal\nSe liga al equiparlo\nÚnico-Equipado\nAbalorio\n[q2]+ 7 Versatilidad\n[q2]Equipar: Cuando sanas o infliges daño tienes la probabilidad de aumentar tu fuerza, agilidad o intelecto 19 p. durante 15 s. Siempre se elige la estadística más elevada.\n[q2]Equipar: Aumenta el efecto de las pociones de sanación y maná en su portador en un 40%. Este efecto no se acumula.\nRequiere Alquimia de Legion (1)\n[q]\"Se puede usar para transmutar en vez de una piedra filosofal.\"\nPrecio de venta: \nRequiere Azufre infernal , Hierba vil (5), Sangre de Sargeras (3)"}
MultiLanguageItemData['mx'][127907] = {name = "Receta: poción de gracia letal", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de gracia letal.\n[q2]Mezcla una poción de gracia letal en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere los Corchos avanzados, los Tubos de vidrio flexibles, y el Filtro de seda Shaldorei\nPrecio de venta: \nPoción de gracia letal\n[q2]Uso: Les concede a tus ataques una probabilidad de liberar un rayo de energía sobre tu objetivo.\n\n Alejarse de los enemigos por toda la duración extenderá el efecto 5 s más. (5 Min Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar , Fjarnskaggl (2), Frondasueño (2), Vial de cristal"}
MultiLanguageItemData['mx'][127908] = {name = "Receta: poción de la guerra antigua", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de la guerra antigua.\n[q2]Mezcla una poción de la guerra antigua en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere los Corchos avanzados, los Tubos de vidrio flexibles, y la Pólvora precipitante\nPrecio de venta: \nPoción de la guerra antigua\n[q2]Uso: Invoca un par de guerreros caídos fantasmales que se unirán a ti en el combate. Pueden emular tus ataques cuerpo a cuerpo y facultades, lo que provoca 1161 de daño. (5 Min Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar , Vulpinia (2), Fjarnskaggl (2), Vial de cristal"}
MultiLanguageItemData['mx'][127909] = {name = "Receta: poción inalterable", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción inalterable.\n[q2]Mezcla una poción inalterable en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere los Corchos avanzados, los Tubos de vidrio flexibles, y el Frasco para mezclas de doble cámara\nPrecio de venta: \nPoción inalterable\n[q2]Uso: Aumenta tu armadura 124 p. durante 25 s. (5 Min Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar , Aethril (2), Vulpinia (2), Vial de cristal"}
MultiLanguageItemData['mx'][127910] = {name = "Receta: poción de torrente ley", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de torrente ley.\n[q2]Mezcla una poción de torrente ley en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere los Corchos avanzados, los Tubos de vidrio flexibles, y el Quemador de llama vil\nPrecio de venta: \nPoción de torrente ley\n[q2]Uso: Hace que quien lo ingiera entre en un estado de concentración elevada en el que puede restaurar hasta ( 300 * 10) p. de maná durante 10 s, pero está indefenso hasta que se rompa la concentración. (5 Min Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar , Aethril (2), Frondasueño (2), Vial de cristal"}
MultiLanguageItemData['mx'][127911] = {name = "Receta: frasco del pacto susurrado", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un frasco del pacto susurrado.\n[q2]Mezcla un frasco del pacto susurrado en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere el Crisol de aliento de demonio, la Asamblea de Bureta malórica, y el Filtro de seda Shaldorei\nPrecio de venta: \nFrasco del pacto susurrado\n[q2]Uso: Aumenta el intelecto 46 p. durante 1 h. Cuenta como elixir de batalla y guardián. El efecto persiste más allá de la muerte. (3 Seg Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar (7), Fjarnskaggl (10), Frondasueño (10), Vial de cristal"}
MultiLanguageItemData['mx'][127912] = {name = "Receta: frasco del séptimo demonio", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un frasco del séptimo demonio.\n[q2]Mezcla un frasco del séptimo demonio en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere el Crisol de aliento de demonio, la Asamblea de Bureta malórica, y la Pólvora precipitante\nPrecio de venta: \nFrasco del séptimo demonio\n[q2]Uso: Aumenta 46 p. la agilidad durante 1 h. Cuenta como elixir de batalla y guardián. El efecto persiste más allá de la muerte. (3 Seg Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar (7), Vulpinia (10), Fjarnskaggl (10), Vial de cristal"}
MultiLanguageItemData['mx'][127913] = {name = "Receta: frasco de los ejércitos interminables", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un frasco de los ejércitos interminables.\n[q2]Mezcla un frasco de los ejércitos interminables en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere el Crisol de aliento de demonio, la Asamblea de Bureta malórica, y el Frasco para mezclas de doble cámara\nPrecio de venta: \nFrasco de los ejércitos interminables\n[q2]Uso: Aumenta la fuerza 46 p. durante 1 h. Cuenta como elixir guardián y de batalla. El efecto persiste más allá de la muerte. (3 Seg Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar (7), Aethril (10), Vulpinia (10), Vial de cristal"}
MultiLanguageItemData['mx'][127914] = {name = "Receta: frasco de las diez mil cicatrices", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un frasco de las diez mil cicatrices.\n[q2]Mezcla un frasco de las diez mil cicatrices en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nRequiere el Crisol de aliento de demonio, la Asamblea de Bureta malórica, y el Quemador de llama vil\nPrecio de venta: \nFrasco de las diez mil cicatrices\n[q2]Uso: Aumenta 69 p. el aguante durante 1 h. Cuenta como elixir de batalla y guardián. El efecto persiste más allá de la muerte. (3 Seg Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar (7), Aethril (10), Frondasueño (10), Vial de cristal"}
MultiLanguageItemData['mx'][127915] = {name = "Receta: caldero de espíritus", additional_info = "Rango 1\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un caldero de espíritus.\n[q2]Fabrica un caldero de espíritus en la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (100)\nRequiere el Conducto de decocción de alta capacidad\nPrecio de venta: \nCaldero de espíritus\n[q7]Se liga a la tropa\n[q2]Uso: Crea un caldero que pueden utilizar los miembros de la banda para obtener el beneficio de un frasco apropiado para su clase y talentos. El caldero tiene 30 usos y dura 10 min.\nPrecio de venta: \nRequiere Frasco del pacto susurrado (5), Frasco del séptimo demonio (5), Frasco de los ejércitos interminables (5), Frasco de las diez mil cicatrices (5), Sangre de Sargeras"}
MultiLanguageItemData['mx'][127916] = {name = "Hallazgos de Altruis", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"Alguien en Azsuna tiene que saber algo de los Pilares de la Creación.\""}
MultiLanguageItemData['mx'][127917] = {name = "Receta: poción de sanación ancestral", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de sanación ancestral de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nYa conocido\nPrecio de venta: \nPoción de sanación ancestral\n[q2]Uso: Restaura 6000 p. de salud. (5 Min Reutilización)\nPrecio de venta:\nRequiere Semilla de yseralina (4), Vial de cristal"}
MultiLanguageItemData['mx'][127918] = {name = "Receta: poción de maná ancestral", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de maná ancestral de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta:\nPoción de maná ancestral\n[q2]Uso: Restaura 2000 p. de maná. (5 Min Reutilización)\nPrecio de venta:\nRequiere Semilla de yseralina (5), Vial de cristal"}
MultiLanguageItemData['mx'][127919] = {name = "Receta: poción de rejuvenecimiento ancestral", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de rejuvenecimiento ancestral de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nPoción de rejuvenecimiento ancestral\n[q2]Uso: Restaura 6000 p. de salud y 1500 p. de maná. (5 Min Reutilización)\nPrecio de venta: \nRequiere Poción de sanación ancestral , Poción de maná ancestral"}
MultiLanguageItemData['mx'][127920] = {name = "Receta: jarabe de magia pura", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un jarabe de magia pura de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nJarabe de magia pura\n[q2]Uso: Tómatela toda.\nPrecio de venta:\nRequiere Aethril (20), Poción de sanación ancestral"}
MultiLanguageItemData['mx'][127921] = {name = "Receta: elixir silvano", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un elixir silvano de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nElixir Sylvan\n[q2]Uso: Transfórmate en árbol. Tú y los jugadores que reposan bajo tu sombra terminan bien descansados, lo que aumenta todas las estadísticas un 10%.\nPrecio de venta:\nRequiere Frondasueño (5), Poción de sanación ancestral"}
MultiLanguageItemData['mx'][127922] = {name = "Receta: elixir de avalancha", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un elixir de avalancha de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nElixir de avalancha\n[q2]Uso: Al caer una gran distancia, te transformas en una avalancha. Cuando aterrizas, infliges 1500 p. de daño a todos los enemigos en un radio de 5 m. (5 Min Reutilización)\nPrecio de venta:\nRequiere Vulpinia (5), Poción de maná ancestral"}
MultiLanguageItemData['mx'][127923] = {name = "Receta: Brebajeskaggl", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer un Brebajeskaggl de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nBrebajeskaggl\n[q2]Uso: Entra al reino espiritual, lo cual otorga invisibilidad a quien lo ingiere durante 18 s. No funciona en niveles superiores a 50. (5 Min Reutilización)\nPrecio de venta:\nRequiere Fjarnskaggl (5), Poción de maná ancestral"}
MultiLanguageItemData['mx'][127924] = {name = "Receta: poción de soplo aéreo", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de soplo aéreo de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nPoción de soplo aéreo\n[q2]Uso: Aumenta la velocidad de movimiento un 150% y hace flotar a quien bebe la poción. Dura 8 s. No funciona en niveles superiores a 50. (5 Min Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar (4), Poción de rejuvenecimiento ancestral"}
MultiLanguageItemData['mx'][127925] = {name = "Receta: piedra de alquimista infernal", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una piedra de alquimista infernal de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \n[q4]Piedra de alquimista infernal\nSe liga al equiparlo\nÚnico-Equipado\nAbalorio\n[q2]+ 7 Versatilidad\n[q2]Equipar: Cuando sanas o infliges daño tienes la probabilidad de aumentar tu fuerza, agilidad o intelecto 19 p. durante 15 s. Siempre se elige la estadística más elevada.\n[q2]Equipar: Aumenta el efecto de las pociones de sanación y maná en su portador en un 40%. Este efecto no se acumula.\nRequiere Alquimia de Legion (1)\n[q]\"Se puede usar para transmutar en vez de una piedra filosofal.\"\nPrecio de venta: \nRequiere Azufre infernal , Hierba vil (5), Sangre de Sargeras (3)"}
MultiLanguageItemData['mx'][127926] = {name = "Receta: poción de gracia letal", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de gracia letal de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nPoción de gracia letal\n[q2]Uso: Les concede a tus ataques una probabilidad de liberar un rayo de energía sobre tu objetivo.\n\n Alejarse de los enemigos por toda la duración extenderá el efecto 5 s más. (5 Min Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar , Fjarnskaggl (2), Frondasueño (2), Vial de cristal"}
MultiLanguageItemData['mx'][127927] = {name = "Receta: poción de la guerra antigua", additional_info = "Rango 2\nSe liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a hacer una poción de la guerra antigua de manera más eficiente.\n[q2]Ya no requiere la estación de alquimia de Dalaran.\nRequiere Alquimia de Legion (1)\nPrecio de venta: \nPoción de la guerra antigua\n[q2]Uso: Invoca un par de guerreros caídos fantasmales que se unirán a ti en el combate. Pueden emular tus ataques cuerpo a cuerpo y facultades, lo que provoca 1161 de daño. (5 Min Reutilización)\nPrecio de venta:\nRequiere Rosa luz estelar , Vulpinia (2), Fjarnskaggl (2), Vial de cristal"}
