MultiLanguageItemData['mx'][128618] = {name = "Fórmula: encantar guantes, minería de Legion", additional_info = "Se liga al recogerlo\nÚnico\nUso: Te enseña a realizar el encantamiento Minería de Legion.\n[q2]Encanta los guantes de forma permanente para aumentar la velocidad de minería en las Islas Quebradas y en Argus.\nRequiere Encantamiento de Legion (1)"}
MultiLanguageItemData['mx'][128619] = {name = "Fórmula: encantar guantes, desuello de Legion", additional_info = "Se liga al recogerlo\nÚnico\nUso: Te enseña a realizar el encantamiento Desuello de Legion.\n[q2]Encanta los guantes de forma permanente para aumentar la velocidad de desuello en las Islas Quebradas y en Argus.\nRequiere Encantamiento de Legion (1)"}
MultiLanguageItemData['mx'][128620] = {name = "Fórmula: encantar guantes, topografía de Legion", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a realizar el encantamiento Topografía de Legion.\n[q2]Encanta los guantes de forma permanente para aumentar la velocidad de reconocimiento arqueológico en las Islas Quebradas.\nRequiere Encantamiento de Legion (1)"}
MultiLanguageItemData['mx'][128621] = {name = "Formula: caldero encantado", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a crear un caldero encantado.\n[q2]Fabrica un caldero encantado.\nRequiere Encantamiento de Legion (1)\n\n\n[q3]Caldero encantado\n[q2]Uso: Te enseña a invocar este compañero.\n[q2]Haz clic con el botón derecho del mouse para invocar y retirar a tu caldero encantado.\nRequiere nivel 1 - 80 ( 80)\nRequiere Cristal del caos (5), Fragmento de luz ley (20), Arkhana (50), Azufre infernal (10)"}
MultiLanguageItemData['mx'][128622] = {name = "Formula: antorcha encantada", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te enseña a crear una Antorcha encantada.\n[q2]Fabrica una antorcha encantada.\nRequiere Encantamiento de Legion (1)\n\n\n[q3]Antorcha encantada\n[q2]Uso: Te enseña a invocar este compañero.\n[q2]Haz clic con el botón derecho del mouse para invocar y retirar a tu antorcha encantada.\nRequiere nivel 1 - 80 ( 80)\nRequiere Cristal del caos (5), Fragmento de luz ley (20), Arkhana (50), Hierba vil (10)"}
