MultiLanguageItemData['mx'][128858] = {name = "[q6]Guadaña de Elune", additional_info = "Se liga al recogerlo\nÚnico\n{Dos manos} {Bastón}\n{2 - 3 p. de daño} {Velocidad 3.60}\n(0.7 p. de daño por segundo)\n+9 intelecto\n+3 aguante\n[q2]Aumenta tu índice de golpe crítico + 2 p.\n[q2]Aumenta tu índice de maestría + 2 p.\n\n[q0]Ranura de reliquia artefacto de Arcano\n[q0]Ranura de reliquia artefacto de Vida\n\nClases: Druida\n[q2]Equipar: Otorga el hechizo Luna nueva, que inflige daño y luego se transforma en un hechizo más poderoso.\n[q]\"Hay un poder interior que quedaría liberado. Con equilibrio y control sería posible domar al lobo, pero solo por un tiempo.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128859] = {name = "[q6]Colmillos de Ashamane", additional_info = "Se liga al recogerlo\nÚnico\n{Mano izquierda} {Daga}\n{1 - 3 p. de daño} {Velocidad 1.80}\n(1.1 p. de daño por segundo)\n+1 agilidad\n+2 aguante\n[q2]Aumenta tu índice de golpe crítico + 1 p.\n[q2]Aumenta tu índice de maestría + 1 p.\nClases: Druida\n[q]\"Ella penetró las filas de demonios y desapareció entre los árboles. Trepó hasta las ramas altas y se abalanzó sobre los comandantes de la Legión. Era el terror de todos, una bestia temible e incontenible, no tenía piedad de nadie.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128860] = {name = "[q6]Colmillos de Ashamane", additional_info = "Se liga al recogerlo\nÚnico\n{Mano derecha} {Daga}\n{1 - 3 p. de daño} {Velocidad 1.80}\n(1.1 p. de daño por segundo)\n+1 agilidad\n+2 aguante\n[q2]Aumenta tu índice de golpe crítico + 1 p.\n[q2]Aumenta tu índice de maestría + 1 p.\n\n[q0]Ranura de reliquia artefacto de Escarcha\n[q0]Ranura de reliquia artefacto de Sangre\n\nClases: Druida\n[q2]Equipar: Otorga la habilidad Frenesí de Ashamane, que desata una serie de tajos sangrientos sobre un objetivo enemigo.\n[q]\"El sacrificio de Ashamane es recordado hasta el día de hoy. Vivimos por su gracia y sus hijos recorren los bosques junto a nosotros como nuestros compañeros más cercanos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128861] = {name = "[q6]Titánica", additional_info = "Se liga al recogerlo\nÚnico\n{A distancia} {Arma de fuego}\n{3 - 6 p. de daño} {Velocidad 3.00}\n(1.5 p. de daño por segundo)\n+2 agilidad\n+3 aguante\n[q2]Aumenta tu índice de golpe crítico + 2 p.\n[q2]Aumenta tu índice de maestría + 2 p.\n\n[q0]Ranura de reliquia artefacto de Tormenta\n[q0]Ranura de reliquia artefacto de Arcano\n\nClases: Cazador\n[q2]Equipar: Hati ahora luchará para ti a tu lado.\n[q]\"Un ejemplo inmejorable de ingeniería tecnomágica, imbuida con el poder de las tormentas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128862] = {name = "[q6]Frío del ébano", additional_info = "Se liga al recogerlo\nÚnico\n{Dos manos} {Bastón}\n{2 - 3 p. de daño} {Velocidad 3.60}\n(0.7 p. de daño por segundo)\n+9 intelecto\n+3 aguante\n[q2]Aumenta tu índice de celeridad + 2 p.\n[q2]Aumenta tu índice de maestría + 2 p.\n\n[q0]Ranura de reliquia artefacto de Escarcha\n[q0]Ranura de reliquia artefacto de Arcano\n\nClases: Mago\n[q2]Equipar: Otorga la habilidad Descarga de Ébano, que inflige un daño enorme de Escarcha de las sombras a un solo objetivo.\n[q]\"El Frío del ébano contenía solo una pizca del poder de Alodi, pero, aun así, era más de lo que la mayoría de los mágicos podría esperar empuñar en su vida.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128864] = {name = "Las montañas rocosas de Altamontaña", additional_info = "Objeto de misión\n[q]\"La saliva de cabra hizo que la tinta se corriera y quedara borrosa.\""}
MultiLanguageItemData['mx'][128866] = {name = "[q6]Veraguardia", additional_info = "Se liga al recogerlo\nÚnico\n{Mano izquierda} {Escudo}\n25 armadura\n+1 fuerza\n+3 intelecto\n+2 aguante\n[q2]Aumenta tu índice de golpe crítico + 1 p.\n[q2]Aumenta tu índice de maestría + 1 p.\n\n[q0]Ranura de reliquia artefacto de Sagrado\n[q0]Ranura de reliquia artefacto de Hierro\n\nClases: Paladín\n[q2]Equipar: Otorga la habilidad Ojo de Tyr, que desata una ráfaga de luz desde tu escudo, debilitando a los enemigos cercanos.\n[q]\"Con la primera caída del martillo, los ríos de magma inundaron las montañas heladas. Con la segunda, la atmósfera gritó y los relámpagos incendiaron los cielos. Con la tercera, un simple rayo de luz solar atravesó las nubes tormentosas y acarició la superficie de Veraguardia.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128867] = {name = "[q6]Cazajuramentos", additional_info = "Se liga al recogerlo\nÚnico\n{Mano derecha} {Espada}\n{2 - 4 p. de daño} {Velocidad 2.60}\n(1.2 p. de daño por segundo)\n+1 fuerza\n+2 aguante\n[q2]Aumenta tu índice de golpe crítico + 1 p.\n[q2]Aumenta tu índice de maestría + 1 p.\nClases: Paladín\n[q]\"Matar por el solo hecho de matar... conquistar solo por conquistar... No hay nada de honor en eso, solo vergüenza y pesar.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128868] = {name = "[q6]Cólera de luz", additional_info = "Se liga al recogerlo\nÚnico\n{Dos manos} {Bastón}\n{2 - 3 p. de daño} {Velocidad 3.60}\n(0.7 p. de daño por segundo)\n+9 intelecto\n+3 aguante\n[q2]Aumenta tu índice de celeridad + 2 p.\n[q2]Aumenta tu índice de maestría + 2 p.\n\n[q0]Ranura de reliquia artefacto de Sagrado\n[q0]Ranura de reliquia artefacto de Sombras\n\nClases: Sacerdote\n[q2]Equipar: Otorga la habilidad Cólera de luz, que desata un torrente de Fuego Sagrado sobre un enemigo. (Probabilidad de que accione: 15%)\n[q]\"Fue con nuestras mayores esperanzas y plegarias que asistimos a la ceremonia ese día... y con gran pena nos retiramos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128869] = {name = "[q6]Las Matarreyes", additional_info = "Pena\nSe liga al recogerlo\nÚnico\n{Mano izquierda} {Daga}\n{1 - 3 p. de daño} {Velocidad 1.80}\n(1.1 p. de daño por segundo)\n+1 agilidad\n+2 aguante\n[q2]Aumenta tu índice de golpe crítico + 1 p.\n[q2]Aumenta tu índice de maestría + 1 p.\nClases: Pícaro\n[q]\"No fue una muerte agradable. Pero fue rápida, silenciosa y eficiente. Tras el último aliento del orco, la herida que lo mató se deformó. Nadie sabría decir si lo mataron con un cuchillo, un hacha o una lanza.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128870] = {name = "[q6]Las Matarreyes", additional_info = "Angustia\nSe liga al recogerlo\nÚnico\n{Mano derecha} {Daga}\n{1 - 3 p. de daño} {Velocidad 1.80}\n(1.1 p. de daño por segundo)\n+1 agilidad\n+2 aguante\n[q2]Aumenta tu índice de golpe crítico + 1 p.\n[q2]Aumenta tu índice de maestría + 1 p.\n\n[q0]Ranura de reliquia artefacto de Sombras\n[q0]Ranura de reliquia artefacto de Hierro\n\nClases: Pícaro\n[q2]Equipar: Te otorga la habilidad Perdición de Reyes, que inyecta a tus objetivos con un veneno de potencia incomparable.\n[q]\"Incontables voces se callaron, e incontables líderes fueron derrocados... todo por el capricho de su infame mando. No habrá redención por estos actos, únicamente soledad y pena.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128872] = {name = "[q6]Los Filos del Terror", additional_info = "Destino\nSe liga al recogerlo\nÚnico\n{Mano derecha} {Espada}\n{2 - 4 p. de daño} {Velocidad 2.60}\n(1.2 p. de daño por segundo)\n+1 agilidad\n+2 aguante\n[q2]Aumenta tu índice de golpe crítico + 1 p.\n[q2]Aumenta tu índice de maestría + 1 p.\n\n[q0]Ranura de reliquia artefacto de Sangre\n[q0]Ranura de reliquia artefacto de Hierro\n\nClases: Pícaro\n[q2]Equipar: Otorga la habilidad Maldición de los Filos del Terror, que te permite usar remates más rápido... por un precio.\n[q]\"Se vio liderando una tripulación de piratas increíblemente grande, capaz de conquistar alta mar y todas las naciones de Azeroth. Todos los barcos que se atrevieron a desafiarla ardieron en llamas y las ciudades entregaban sus tesoros o eran destruidas.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][128873] = {name = "[q6]La furia de la Madre Pétrea", additional_info = "Se liga al recogerlo\nÚnico\n{Mano izquierda} {Maza}\n{2 - 3 p. de daño} {Velocidad 2.60}\n(1.0 p. de daño por segundo)\n+1 agilidad\n+2 aguante\n[q2]Aumenta tu índice de golpe crítico + 1 p.\n[q2]Aumenta tu índice de maestría + 1 p.\nClases: Chamán\n[q]\"Creada a través del poder del Martillo maldito y del poderoso chamán que lo blande.\"\nPrecio de venta:"}
