MultiLanguageItemData['mx'][132374] = {name = "[q5]Maldición final de Kazzak", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cintura} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 70 / 70\nClases: Brujo\n[q2]Equipar: Fatalidad inflige un 5% de daño aumentado por cada mascota demoníaca que tengas activa.\n[q]\"Cuando el Señor de fatalidad pasó por el Portal Oscuro hacia Terrallende, les dejó un regalo de despedida a sus enemigos...\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132375] = {name = "[q5]Odr, chal de los ymirjar", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\nEspalda\n3 armadura\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\nClases: Brujo\n[q2]Equipar: Los enemigos marcados con tu Estragos reciben un 15% de daño aumentado con tus hechizos de objetivo único.\n[q]\"Lo encontraron inmaculado bajo escombros quemados en la aldea de Ymirheim.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132376] = {name = "[q5]Mantón de Acherus", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\nEspalda\n3 armadura\n+3 fuerza\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nClases: Caballero de la muerte\n[q2]Equipar: Aumenta la duración de Caparazón antimagia en 100% y cualquier daño que absorba te sanará.\n[q]\"Pues no me enfrentas a solas, sino con la mismísima Espada de Ébano. Somos inmortales, somos imparables, ¡y deseamos vivir!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132377] = {name = "Brújula de Ariden", additional_info = "Objeto de misión\n[q]\"Una antigua y maltrecha brújula relacionada con los jinetes oscuros del Paso de la Muerte.\""}
MultiLanguageItemData['mx'][132378] = {name = "[q5]Golpe oscuro de Sacrolátigo", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nDedo\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 7 p.\n[q2]Aumenta tu índice de maestría + 7 p.\n\n[q0]Ranura prismática\n\nClases: Brujo\n[q2]Equipar: Corrupción inflige un 15% más de daño y ralentiza la velocidad de movimiento del enemigo un 60%.\n[q]\"Miseria... confusión... recelo. Estas son las señales.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132379] = {name = "[q5]Maldad de los Sin'dorei", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Tela}\n2 armadura\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\nDurabilidad 70 / 70\nClases: Brujo\n[q2]Equipar: Durante 25 s después de lanzar Invocar guardia apocalíptico, Invocar infernal o Invocar tirano demoníaco, tú y tus esbirros infligen un 15% más de daño. [ Grimorio de supremacía : Este efecto se puede obtener solo una vez cada 3 min ]\n[q]\"Muchos de los nuestros han sido influenciados y dominados por la Legión Ardiente. Lo correcto es que usemos sus propios ejércitos en su contra.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132381] = {name = "[q5]Grilletes de insomnio de Streten", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Tela}\n2 armadura\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 70 / 70\nClases: Brujo\n[q2]Equipar: Todo el daño que infliges aumenta un 4% por cada enemigo afectado por tu Aflicción inestable.\n[q]\"El único riesgo es perder la cordura.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132393] = {name = "[q5]Ritual recurrente", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Hombro} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 120 / 120\nClases: Brujo\n[q2]Equipar: Invocar Acechadores nefastos recupera 1 fragmento de alma.\n[q]\"Los forasteros siempre se sorprendían con la forma en que los brujos vrykul lograban invocar y controlar enormes manadas de acechadores viles.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132394] = {name = "[q5]Capucha de desdén eterno", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cabeza} {Tela}\n4 armadura\n+5 intelecto\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de maestría + 6 p.\nDurabilidad 120 / 120\nClases: Brujo\n[q2]Equipar: Agonía inflige su daño completo un 10% más rápido.\n[q]\"Quien use esta capucha obtendrá una fuerza y voluntad impías, pero perderá para siempre toda la bondad y compasión. Ten cuidado...\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132406] = {name = "[q5]Ataduras de marquesina del Rey del Sol", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Tela}\n2 armadura\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\nDurabilidad 70 / 70\nClases: Mago\n[q2]Equipar: Luego de consumir Una buena racha, hay un 15% de probabilidad de que el siguiente lanzamiento no instantáneo de Piroexplosión que suceda en los siguientes 15 s s inflija un 300% más de daño.\n[q]\"A diferencia de lo que todos creen, ¡el ataque final y preferido de Kael'thas contra sus enemigos era \"PIROEXPLOSIÓN\"!\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132407] = {name = "[q5]Restricciones de Magigolpe", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Tela}\n2 armadura\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 70 / 70\nClases: Brujo\n[q2]Equipar: Descarga de Caos tiene un 20% de probabilidad de atacar a un enemigo más en un radio de 30 m. (Probabilidad de que accione: 20%)\n[q]\"Varo'then estaba profundamente enamorado de la reina. Desafortunadamente, nunca tuvo la oportunidad de usar estas ataduras con ella.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132409] = {name = "[q5]Grilletes abrasados de Anund", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Tela}\n2 armadura\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 70 / 70\nClases: Sacerdote\n[q2]Equipar: Cada vez que tu Palabra de las Sombras: dolor y tu Toque vampírico infligen daño, tu Descarga del Vacío obtiene un 3% de daño aumentado, el cual se acumula hasta 50 veces.\n[q]\"Nadie sabe por qué Anund se encontraba frente a Kaldrigos. Sin embargo, la leyenda dice que la última Palabra de las Sombras: dolor de Anund fue lo que ayudó a Korl en su derrota del temible vermis.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132410] = {name = "[q5]Esquirla del Exodar", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nDedo\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 9 p.\n[q2]Aumenta tu índice de celeridad + 5 p.\n\n[q0]Ranura prismática\n\nClases: Mago\n[q2]Equipar: Distorsión temporal no te aplica Desplazamiento temporal y no se ve afectado por Desplazamiento temporal u otro efecto parecido.\n[q]\"La ciudad capital de los draenei es capaz de transcender dimensiones e incluso distorsionar el tiempo. ¿Qué podría hacer un simple mortal con una fracción de su poder?\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132411] = {name = "[q5]Agarre de Lady Vashj", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Manos} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 70 / 70\nClases: Mago\n[q2]Equipar: Mientras Venas heladas está activo, obtienes 1 p. de carga de Dedos de Escarcha cada 10 s.\n[q]\"Imbuidos con el poder de la bruja del mar naga, sientes los dedos fríos por dentro pero sorprendentemente ágiles y altamente energizados.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132413] = {name = "[q5]Brazaletes de asalto de Rhonin", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Tela}\n2 armadura\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 2 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\nDurabilidad 70 / 70\nClases: Mago\n[q2]Equipar: Misiles Arcanos tiene un 18% de probabilidad de hacer que tu siguiente Explosión Arcana dentro de los siguientes 6 s no cueste maná. (Probabilidad de que accione: 18%)\n[q]\"Los magos con tanto poder como Rhonin, un antiguo líder del Kirin Tor, suelen usar vinculaciones arcanas para estabilizar la magia emitida desde la punta de sus dedos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132436] = {name = "[q5]Skjoldr, Santuario de Ivagont", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Tela}\n2 armadura\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de celeridad + 4 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 70 / 70\nClases: Sacerdote\n[q2]Equipar: Tu Palabra de poder: escudo absorbe un 15% más y reduce 4 s el tiempo de reutilización restante de Supresión de dolor.\n[q]\"Ivagont luchó al lado de Kakushan, como siempre, durante la masacre de los naga Escama tormentosa en Costa Oscura. Gracias a su protección, salieron intactos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132437] = {name = "[q5]Seducción de la Madre Shahraz", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Hombro} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 120 / 120\nClases: Sacerdote\n[q2]Equipar: Obtienes 3 acumulaciones de Forma del vacío cuando adoptas Forma del vacío.\n[q]\"Lucías algo tenso...\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132438] = {name = "Talismán de ascensión", additional_info = "Objeto de misión\n[q]\"(NYI - Requires Revered with Valkyra) Given to Valkyra who have proven themselves ready to ascend to the highest ranks of their order.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132440] = {name = "La Svalnguardia", additional_info = "Objeto de misión\n[q]\"Gran escudo de Odyn, señor de los Salones del Valor.\""}
MultiLanguageItemData['mx'][132441] = {name = "[q5]Draugr, faja del Rey Eterno", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cintura} {Placas}\n10 armadura\n+4 [Fuerza o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de celeridad + 5 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 70 / 70\nClases: Caballero de la muerte\n[q2]Equipar: Golpe purulento tiene un 30% de probabilidad de devolver 1 runa. (Probabilidad de que accione: 30%)\n[q]\"La leyenda dice que los cuerpos de los engendros titanes están tan saturados de energía de los creadores que dejan caer fragmentos cuando el portador mortal muere. Dicen que esta faja fue fabricada con esos fragmentos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132442] = {name = "[q5]Cinturón de infinidad", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cintura} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 70 / 70\nClases: Mago\n[q2]Equipar: Aumenta un 10% el daño que inflige Misiles arcanos.\n[q2]Equipar: Cada vez que Misiles arcanos golpea a un enemigo, el daño de tu siguiente Marca de Aluneth aumenta un 1.0%. Este efecto se acumula.\n[q]\"La magia contenida en su interior parecía ser tan interminable como la Legión Ardiente.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132443] = {name = "[q5]Zancada de Aggramar", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pies} {Placas}\n11 armadura\n+4 [Fuerza o Intelecto]\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 95 / 95\nClases: Guerrero , Paladín , Caballero de la muerte\n[q2]Equipar: Aumenta tu velocidad de movimiento un 75% de tu celeridad, golpe crítico, maestría o versatilidad (la que sea más alta).\n[q]\"El tiempo y el espacio son uno solo. Para un vigía del universo, la distancia no tiene importancia.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132444] = {name = "[q5]Prydaz, ópera prima de Xavaric", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\nCuello\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 6 p.\n[q2]Aumenta tu índice de celeridad + 6 p.\n[q2]Aumenta tu índice de maestría + 6 p.\n\n[q0]Ranura prismática\n[q2]Equipar: Cada 30 s, obtienes un escudo de absorción equivalente al 25% de tu salud máxima durante 30 s.\n[q]\"Los usuarios de este amuleto silban una mortificadora canción, y quienes la escucharon aseguran reconocer un distante grito de angustia entre cada nota.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132445] = {name = "[q5]Al'maiesh, la cuerda de la esperanza", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cintura} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 5 p.\nDurabilidad 70 / 70\nClases: Sacerdote\n[q2]Equipar: Si activas Serendipia y Palabra Sagrada no está en tiempo de reutilización, Serendipia aumenta el daño y la sanación de tu siguiente lanzamiento de Palabra Sagrada en 10%. Se acumula hasta 5 veces.\n[q]\"Dicen que esto solía pertenecer al primer val'kyr.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132446] = {name = "Joyas de Jabrul", additional_info = "Objeto de misión\n[q]\"Un saco grande que contiene joyas diversas.\""}
MultiLanguageItemData['mx'][132447] = {name = "[q5]Calzas fascinantes de An'juna", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Piernas} {Tela}\n4 armadura\n+5 intelecto\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 6 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 145 / 145\nClases: Sacerdote\n[q2]Equipar: Aumenta la duración de Renovar 6 s.\n[q]\"Los usuarios de estas calzas suelen responder sobremanera a la llamada del deber.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132448] = {name = "[q5]La cuarta lección del instructor", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Placas}\n9 armadura\n+3 [Fuerza o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\nDurabilidad 70 / 70\nClases: Caballero de la muerte\n[q2]Equipar: Golpe de la Plaga tiene un 1-2 de probabilidad de lanzar Herida degenerativa adicional.\n[q]\"No se sabe cómo esta banda, supuestamente regalada por Razuvious a sus acólitos más talentosos, escapó de los muros de Naxxramas. ¿Sería posible que el Rey Exánime estuviera enviando a sus propios agentes a las Islas Quebradas?\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132449] = {name = "[q5]Abrazo de Phyrix", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nDedo\n+4 aguante\n[q2]Aumenta tu índice de celeridad + 9 p.\n[q2]Aumenta tu índice de maestría + 5 p.\n\n[q0]Ranura prismática\n\nClases: Sacerdote\n[q2]Equipar: Aumenta un 50% la duración de Espíritu guardián y su bonificación de sanación. Además, Espíritu guardián ya no termina su efecto de sanación de bonificación al sacrificarse.\n[q]\"Phyrix era un sacerdote legendario que lideró aventuras en el Núcleo de Magma y la Guarida de Alanegra. Encontró un desafortunado final a manos de Nefarian, pero su espíritu aún protege a los campeones de Azeroth hasta el día de hoy.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132450] = {name = "[q5]Voluntad inquebrantable de Muze", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Tela}\n2 armadura\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 2 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\nDurabilidad 70 / 70\nClases: Sacerdote\n[q2]Equipar: Cuando tienes más de un 75% de salud, los tiempos de lanzamiento de Sanación relámpago, Sanar, Rezo de sanación y Punición se reducen un 15%.\n[q]\"Desde sus humildes comienzos en la Lunargenta a las profundidades de la Montaña Roca Negra, Muze mantuvo su determinación y sanó a sus compañeros fielmente, salvándolos de las garras de la muerte.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132451] = {name = "[q5]Falda mística del Maestro de Runas", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Piernas} {Tela}\n4 armadura\n+5 intelecto\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 6 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 145 / 145\nClases: Mago\n[q]\"Aunque, por naturaleza, los medio gigantes de Rasganorte no saben casi nada de magia, los místicos vrykul de Stormheim son maestros de la magia rúnica.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132452] = {name = "[q5]Secreto de Sephuz", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nDedo\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 10 p.\n[q2]Aumenta tu índice de celeridad + 4 p.\n\n[q0]Ranura prismática\n[q2]Equipar: Otorga un 10% más de velocidad de movimiento y un 2% de celeridad. Si logras aplicar un efecto de pérdida de control a un enemigo, interrumpir a un enemigo o disipar cualquier objetivo, este efecto aumenta a un 70% más de velocidad de movimiento y un 25% de celeridad durante 10 s. Este incremento puede ocurrir una vez cada 30 s.\n[q]\"La intangibilidad es un concepto curioso. La palabra sugiere algún tipo de habilidad mágica, pero en el mundo físico, simplemente significa el poder de estar aquí o ahí, ahora o después.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132453] = {name = "[q5]Quijotes de hueso de Traquesangre", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Piernas} {Placas}\n16 armadura\n+5 [Fuerza o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 4 p.\n[q2]Aumenta tu índice de maestría + 6 p.\nDurabilidad 145 / 145\nClases: Caballero de la muerte\n[q2]Equipar: Escudo óseo otorga un 10% más de armadura y aumenta 60 p. tu poder rúnico máximo.\n[q]\"Partes del horror desgarbado del Traquesangre aún contienen poderosas energías nigrománticas que responden a la voluntad de quienes tengan la fuerza de dominarlos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132454] = {name = "[q5]Toque ardiente de Koralon", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cintura} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\nDurabilidad 70 / 70\nClases: Mago\n[q2]Equipar: Agostar causa 350% de daño aumentado y es un golpe crítico garantizado contra enemigos que tengan menos de un 30% de salud.\n[q]\"En las profundidades de la bóveda protegida por Conquista del Invierno, Koralon el Vigía de las Llamas se enfurecía cuando entraban intrusos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132455] = {name = "[q5]Previsión de Norgannon", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pies} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 4 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 95 / 95\nClases: Sacerdote , Mago , Brujo\n[q2]Equipar: No moverte durante 6 s te otorga Previsión, lo que te permite lanzar mientras te mueves durante 4 s. Esta duración comienza cuando empiezas a moverte.\n[q]\"La magia debe ser regulada, administrada y controlada. Pero también debe ser apreciada y valorada, no acumulada. Esa es la paradoja que debes comprender.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132456] = {name = "[q5]Relicario de almas", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cintura} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de celeridad + 4 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 70 / 70\nClases: Brujo\n[q2]Equipar: Lanzar un hechizo de Fuego dañino tiene un 6% de probabilidad de generar un Fragmento de alma. (Probabilidad de que accione: 6%)\n[q]\"Visto desde diferentes ángulos, parece haber un leve reflejo de tres rostros distintos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132457] = {name = "[q5]Cordón de poder de Lethtendris", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cintura} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 5 p.\nDurabilidad 70 / 70\nClases: Brujo\n[q2]Equipar: Lanzar Aflicción inestable sobre un objetivo que no tenga aún Aflicción inestable tiene un 25% de probabilidad de devolver el costo de Fragmento de alma.\n[q]\"Lethtendris construyó un aparato para canalizar el abrumador poder corrupto de la Masacre para sí misma.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132458] = {name = "[q5]Ataduras de tormenta de nieve de Toravon", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Muñecas} {Placas}\n9 armadura\n+3 [Fuerza o Intelecto]\n+4 aguante\n[q2]Aumenta tu índice de celeridad + 3 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 70 / 70\nClases: Caballero de la muerte\n[q2]Equipar: Mientras Pilar de Escarcha esté activo, infliges un 15% más de daño de Escarcha.\n[q]\"En las profundidades de la bóveda protegida por Conquista del Invierno, Tovaron el Vigía del Hielo era incansable al aplastar a los intrusos.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132459] = {name = "[q5]Perseverancia del Mártir de Ébano", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cabeza} {Placas}\n13 armadura\n+5 [Fuerza o Intelecto]\n+7 aguante\n[q2]Aumenta tu índice de celeridad + 6 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 120 / 120\nClases: Caballero de la muerte\n[q2]Equipar: Explosión aullante inflige un 20% más de daño a los enemigos que han recibido daño reciente de tu Invierno sin remordimientos.\n[q]\"El frío acero de esta corona presiona fuertemente la cabeza de quien la usa.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132460] = {name = "[q5]Pirogénica de Alythess", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nDedo\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 8 p.\n[q2]Aumenta tu índice de celeridad + 6 p.\n\n[q0]Ranura prismática\n\nClases: Brujo\n[q2]Equipar: Los enemigos afectados por tu Lluvia de Fuego reciben un 10% de daño aumentado de tus hechizos de Fuego.\n[q]\"Depravación... odio... caos. Estos son los pilares.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132461] = {name = "[q5]Xalan, la presa del temido", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Manos} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de maestría + 3 p.\nDurabilidad 70 / 70\nClases: Sacerdote\n[q2]Equipar: Cuando tu Penitencia inflige daño, la duración de Contrición en ti aumenta 3 s. Cuando tu Penitencia sana, la duración de Contrición sobre tu objetivo aumenta 3 s.\n[q]\"Arrancado de las manos de Xalan por elfos de la noche durante la guerra de los sátiros.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132462] = {name = "Costillar de Tronacuerno", additional_info = "Objeto de misión\n[q]\"Carne suficiente para alimentar a mil guerreros.\""}
