MultiLanguageItemData['mx'][132861] = {name = "[q5]Estel, la inspiración de Dejahna.", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Pecho} {Tela}\n5 armadura\n+5 intelecto\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 6 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 200 / 200\nClases: Sacerdote\n[q2]Equipar: Aumenta un 3% la sanación realizada.\n[q2]Equipar: Súplica aumenta tu celeridad un 1% por cada objetivo bajo los efectos de tu Contrición durante 8 s.\n[q]\"La fe es el comienzo de todas las cosas. Si tu habilidad con lo arcano es decente, pero no fuerte, igualmente puedes ser una hechicera. Pero si tu fe solo es decente, pero no fuerte, nunca serás una sacerdotisa.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132862] = {name = "Anillo de los Caídos", additional_info = "Objeto de misión\n[q]\"En la parte superior del anillo hay un ópalo negro con una niebla en espiral que recuerda algo similar a un alma.\""}
MultiLanguageItemData['mx'][132863] = {name = "[q5]Diadema de fuego de dragón Darckli", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cabeza} {Tela}\n4 armadura\n+5 intelecto\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 6 p.\n[q2]Aumenta tu índice de celeridad + 4 p.\nDurabilidad 120 / 120\nClases: Mago\n[q2]Equipar: Aumenta un 100% el daño y 25 m el alcance de Aliento de dragón.\n[q]\"Entre los innmumerables logros del Archimago Darckli se contaba dominar el arte de respirar fuego de dragón directamente de su boca.\"\nPrecio de venta:"}
MultiLanguageItemData['mx'][132864] = {name = "[q5]Locura de Mangaza", additional_info = "Se liga al recogerlo\nÚnico-Equipado: Legendario de Legion (1)\n{Cintura} {Tela}\n3 armadura\n+4 intelecto\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\nDurabilidad 70 / 70\nClases: Sacerdote\n[q2]Equipar: Aumenta la cantidad de cargas máximas de Explosión mental en 1.\n[q]\"Mangaza de los Kaldorei era un pionero entre su gente por su dedicación a un nuevo tipo de magia, que elegía atacar la mente en lugar del cuerpo. Trágicamente, este método terminó por hacerle perder la cordura, al igual que a sus víctimas.\"\nPrecio de venta:"}
